function blankState(){const next=structuredClone(defaults);for(const k of WORKSPACE_COLLECTIONS)next[k]=[];return next}
function load(){const next=blankState();try{const raw=localStorage.getItem(DEVICE_STORAGE);if(!raw)return next;const saved=JSON.parse(raw);next.view=saved.view||'home';next.settingsTab=saved.settingsTab||'general';next.tabs={...next.tabs,...(saved.tabs||{})};next.preferences={...next.preferences,...(saved.preferences||{})};next.security={...(saved.security||{})};next.privacy={...(saved.privacy||{})};return next}catch{return next}}
const state=load();
const WORKSPACE_CACHE_PREFIX='qanteak.rc9.workspace.cache.';
function workspaceCacheKey(){const id=backendState?.workspaceId||state.preferences?.cloudWorkspaceId||'';return id?`${WORKSPACE_CACHE_PREFIX}${id}`:''}
function workspaceSnapshotForCache(){const out={};for(const k of WORKSPACE_COLLECTIONS)out[k]=structuredClone(state[k]||[]);return out}
function persistWorkspaceCache(){try{const key=workspaceCacheKey();if(!key||(!backendState?.workspaceLoaded&&!backendState?.cacheHydrated))return;localStorage.setItem(key,JSON.stringify({revision:Number(backendState?.revision||0),savedAt:new Date().toISOString(),snapshot:workspaceSnapshotForCache()}));}catch(e){console.warn('Workspace cache write skipped',e?.message||e)}}
function restoreWorkspaceCache(){try{const key=workspaceCacheKey();if(!key)return false;const raw=localStorage.getItem(key);if(!raw)return false;const cached=JSON.parse(raw);const snap=cached?.snapshot;if(!snap||typeof snap!=='object')return false;for(const k of WORKSPACE_COLLECTIONS)state[k]=Array.isArray(snap[k])?structuredClone(snap[k]):[];backendState.cacheHydrated=true;backendState.revision=Math.max(Number(backendState.revision||0),Number(cached.revision||0));return true}catch(e){console.warn('Workspace cache restore skipped',e?.message||e);return false}}
function clearWorkspaceCollections(){for(const k of WORKSPACE_COLLECTIONS)state[k]=[]}
function persistDeviceState(){try{localStorage.setItem(DEVICE_STORAGE,JSON.stringify({view:state.view,tabs:state.tabs,settingsTab:state.settingsTab,preferences:state.preferences,security:state.security,privacy:state.privacy}))}catch{}}
const prefersDark=window.matchMedia?.('(prefers-color-scheme: dark)');
function resolvedAppearance(){const p=state.preferences?.appearance||'light';return p==='system'?(prefersDark?.matches?'dark':'light'):p}
function applyAppearance(){const resolved=resolvedAppearance();document.documentElement.dataset.theme=resolved;document.documentElement.dataset.appearanceMode=state.preferences?.appearance||'light';const brand=$('#brandLogo');if(brand){brand.src='assets/qanteak-logo-white.png';brand.dataset.logoTone='light'}const auth=$('#authLogo');if(auth){auth.src=resolved==='dark'?'assets/qanteak-logo-white.png':'assets/qanteak-logo-black.png';auth.dataset.logoTone=resolved==='dark'?'light':'dark'}const metaTheme=document.querySelector('meta[name="theme-color"]');if(metaTheme)metaTheme.content=resolved==='dark'?'#0b0d12':'#f4f6f8'}
function setAppearance(mode){if(!['light','dark','system'].includes(mode))return;const previous=state.preferences?.appearance||'light';if(previous===mode){applyAppearance();return}state.preferences={...(state.preferences||{}),appearance:mode};save();applyAppearance();if(state.view==='settings')render('settings');toast('Appearance updated',mode==='system'?'Qanteak now follows your Windows appearance.':`Qanteak switched to ${mode} mode.`,'good')}
function save(){persistDeviceState();updateNotificationCount();if(backendState?.session&&backendState?.workspaceId)scheduleCloudSync()}

const meta={
  home:['Home','Your command center for work, clients and business.'],
  work:['Work','Projects, tasks, calendar and planning.'],
  clients:['Clients','Relationships, portals and CRM.'],
  documents:['Documents','Briefs, notes, SOPs and knowledge.'],
  files:['Files','Connected assets, versions and delivery state.'],
  business:['Business','Invoices, estimates, expenses and profitability.'],
  automations:['Automations','Triggers, conditions and actions across Qanteak.'],
  settings:['Settings','Workspace preferences, updates and local data.']
};
const money=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(n)||0);
const projectByName=name=>state.projects.find(p=>p.name===name);
const statusKind=s=>/overdue|risk|due tomorrow|needs/i.test(s)?'bad':/review|waiting|planning/i.test(s)?'warn':'good';

function tabs(view,items){return `<div class="tabs">${items.map(([id,label])=>`<button class="tab ${state.tabs[view]===id?'active':''}" data-tab-view="${view}" data-tab="${id}">${label}</button>`).join('')}</div>`}
function sectionTitle(title,sub,action=''){return `<div class="sectionHead"><div><h3>${title}</h3><p>${sub}</p></div>${action}</div>`}
function projectRows(){return state.projects.slice(0,4).map(p=>`<div class="projectRow"><div class="projectName"><div class="projectMark">${esc(p.name.split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</div><div><b>${esc(p.name)}</b><span>${esc(p.client)} · ${esc(p.status)}</span></div></div><div><div class="progress"><i style="width:${Math.min(100,p.progress)}%"></i></div><div class="progressLabel"><span>Progress</span><b>${p.progress}%</b></div></div><span class="chip ${statusKind(p.status)}">${esc(p.status)}</span><button class="miniButton" data-open-project="${p.id}">Open</button></div>`).join('')}
function taskRows(tasks=state.tasks){return tasks.map(t=>`<div class="taskItem ${t.done?'done':''}"><button class="taskCheck" data-task="${t.id}">${t.done?'✓':''}</button><div><b>${esc(t.title)}</b><span>${esc(t.project)}</span></div><time>${esc(t.due)}</time></div>`).join('')}

function home(){
  const d=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'short',day:'numeric'}).format(new Date());
  const outstanding=state.invoices.filter(i=>i.status!=='Paid').reduce((a,b)=>a+b.amount,0);
  const overdue=state.invoices.filter(i=>i.status==='Overdue').length;
  const openTasks=state.tasks.filter(t=>!t.done).length;
  return `<div class="welcome"><div><h2>Good morning, Hamza.</h2><p>Here is what needs attention across Qanteak today.</p></div><div class="dateChip">${d}</div></div>
  <div class="grid metrics">
    ${[['Tasks open',openTasks,'Today','good','Across active projects'],['Reviews waiting',state.reviews.filter(r=>r.status!=='Approved').length,'Client review','warn','Approvals and feedback'],['Outstanding',money(outstanding),`${overdue} overdue`,'bad','Invoices that still need payment'],['Active projects',state.projects.length,'Live','good','Client and internal work']].map(m=>`<article class="card metric"><div class="metricLabel"><span>${m[0]}</span><span>↗</span></div><div class="metricValue"><strong>${m[1]}</strong><span class="chip ${m[3]}">${m[2]}</span></div><p>${m[4]}</p></article>`).join('')}
  </div>
  <div class="grid dashboard"><div class="stack">
    <article class="card sectionCard">${sectionTitle('Current projects','Status, progress and next action.','<button class="textButton" data-view-jump="work">View all</button>')}${projectRows()}</article>
    <article class="card sectionCard">${sectionTitle('Business snapshot','Current month and outstanding work.','<button class="textButton" data-view-jump="business">Open business</button>')}<div class="grid moneyGrid"><div class="moneyCard"><span>Revenue</span><b>$12,000</b><p>Current month</p></div><div class="moneyCard"><span>Expenses</span><b>${money(state.expenses.reduce((a,b)=>a+b.amount,0))}</b><p>Tracked expenses</p></div><div class="moneyCard"><span>Outstanding</span><b>${money(outstanding)}</b><p>${overdue} overdue invoice</p></div><div class="moneyCard"><span>Active work</span><b>${state.projects.length}</b><p>Connected projects</p></div></div></article>
  </div><div class="stack">
    <article class="card sectionCard">${sectionTitle('Needs attention','Prioritized across your workspace.')}<div class="attentionItem"><span class="dot bad"></span><div><b>Invoice #104 is overdue</b><span>Nike · $2,400 outstanding</span></div><time>7d</time></div><div class="attentionItem"><span class="dot warn"></span><div><b>Client approval waiting</b><span>Nike Campaign · Key visual review</span></div><time>3d</time></div><div class="attentionItem"><span class="dot warn"></span><div><b>Wedding Film deadline</b><span>Final export and delivery package</span></div><time>1d</time></div></article>
    <article class="card sectionCard">${sectionTitle('Today','Your task queue.','<button class="textButton" data-create="task">Add task</button>')}<div id="taskList">${taskRows(state.tasks.slice(0,5))}</div></article>
    <article class="card aiCard"><div class="aiTop"><small>Qanteak AI daily brief</small><h3>Three things deserve your attention.</h3><p>Nike is waiting on approval, one invoice is overdue, and tomorrow's delivery still needs a final export.</p></div><div class="aiBottom"><button class="textButton" id="openBriefAi">Ask Qanteak about my day →</button></div></article>
  </div></div>`
}

function workProjects(){
  const columns=['Planning','In progress','Client review','Delivery'];
  return `<div class="grid overview"><article class="card kpiCard"><h3>Active projects</h3><p>Current client and internal work.</p><strong>${state.projects.length}</strong></article><article class="card kpiCard"><h3>Tasks this week</h3><p>Assigned or owned by you.</p><strong>${state.tasks.filter(t=>!t.done).length}</strong></article><article class="card kpiCard"><h3>At risk</h3><p>Deadline or dependency needs attention.</p><strong>${state.projects.filter(p=>/review|delivery/i.test(p.status)).length}</strong></article></div><article class="card sectionCard">${sectionTitle('Project board','Structured workflow with clear ownership.','<button class="textButton" id="saveWorkView">Save view</button>')}<div class="grid kanban">${columns.map(c=>{const ps=state.projects.filter(p=>p.status.toLowerCase()===c.toLowerCase());return `<div class="kanbanCol"><div class="kanbanHead">${c}<span>${ps.length}</span></div>${ps.map(p=>`<div class="kanbanCard" data-open-project="${p.id}"><b>${esc(p.name)}</b><p>${esc(p.description)}</p><div class="kanbanMeta"><span>${p.progress}% complete</span><span>${esc(p.due)}</span></div></div>`).join('')||'<div class="empty">No projects</div>'}</div>`}).join('')}</div></article><div class="grid twoCol"><article class="card sectionCard">${sectionTitle('My tasks','Open work across all projects.','<button class="textButton" data-create="task">Add task</button>')}<div id="taskList">${taskRows(state.tasks)}</div></article><article class="card sectionCard">${sectionTitle('Recent activity','What changed across work.')}<div class="notification"><span class="dot"></span><div><b>Nike review updated</b><span>New client feedback was added.</span></div></div><div class="notification"><span class="dot"></span><div><b>Wedding Film moved to Delivery</b><span>92% complete with final export pending.</span></div></div><div class="notification"><span class="dot"></span><div><b>Brand Identity files changed</b><span>New guidelines version added.</span></div></div></article></div>`
}
function workTasks(){return `<article class="card sectionCard">${sectionTitle('Tasks','Everything assigned to you or your workspace.','<button class="primary" data-create="task">+ Task</button>')}<div id="taskList">${taskRows(state.tasks)}</div></article>`}
function workCalendar(){const days=['Mon','Tue','Wed','Thu','Fri'];return `<article class="card sectionCard">${sectionTitle('Calendar','A simple work-week view of due tasks.')}<div class="calendarGrid">${days.map((d,i)=>`<div class="dayCard"><h4>${d} · Sep ${7+i}</h4>${state.tasks.filter((_,idx)=>idx%5===i&&!state.tasks[idx].done).map(t=>`<div class="calendarTask"><b>${esc(t.title)}</b><span>${esc(t.project)}</span></div>`).join('')}</div>`).join('')}</div></article>`}
function workTimeline(){return `<article class="card sectionCard">${sectionTitle('Timeline','Project progress and delivery focus.')}<div class="timeline">${state.projects.map(p=>`<div class="timelineRow"><div><b>${esc(p.name)}</b><span class="sub">${esc(p.client)}</span></div><div class="timelineBar"><i style="width:${Math.max(12,p.progress)}%">${p.progress}%</i></div><div>${esc(p.due)}</div></div>`).join('')}</div></article>`}
function work(){const tab=state.tabs.work;const body=tab==='tasks'?workTasks():tab==='calendar'?workCalendar():tab==='timeline'?workTimeline():workProjects();return `<div class="surfaceToolbar">${tabs('work',[['projects','Projects'],['tasks','Tasks'],['calendar','Calendar'],['timeline','Timeline']])}<button class="primary" data-create="project">+ Project</button></div>${body}`}

function clientsMain(){return `<div class="grid overview"><article class="card kpiCard"><h3>Active clients</h3><p>Clients with current work.</p><strong>${state.clients.length}</strong></article><article class="card kpiCard"><h3>Client value</h3><p>Revenue from active relationships.</p><strong>${money(state.clients.reduce((a,b)=>a+b.value,0))}</strong></article><article class="card kpiCard"><h3>Waiting approvals</h3><p>Portal/review requests pending.</p><strong>${state.reviews.filter(r=>r.status!=='Approved').length}</strong></article></div><div class="grid clientGrid">${state.clients.map(c=>`<article class="card clientCard" data-open-client="${c.id}"><div class="projectMark">${esc(c.name.split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</div><h4>${esc(c.name)}</h4><span>${esc(c.relationship)}</span><div class="clientStats"><div><b>${money(c.value)}</b><span>Lifetime value</span></div><div><b>${c.projects}</b><span>Projects</span></div><div><b>${money(c.outstanding)}</b><span>Outstanding</span></div></div></article>`).join('')}</div><article class="card sectionCard">${sectionTitle('Recent client activity','One timeline across comments, approvals and billing.')}<div class="notification"><span class="dot"></span><div><b>Nike left a review comment</b><span>“Can we see the alternate headline?” on Key Visuals.</span></div></div><div class="notification"><span class="dot"></span><div><b>North Studio approved a proposal</b><span>Estimate EST-018 was accepted.</span></div></div><div class="notification"><span class="dot"></span><div><b>Sarah & Adam invoice viewed</b><span>Final payment invoice opened.</span></div></div></article>`}
function clientsLeads(){return `<article class="card sectionCard">${sectionTitle('Lead pipeline','Track opportunities before they become clients.','<button class="primary" data-create="lead">+ Lead</button>')}<div class="listCard">${state.leads.map(l=>`<div class="listRow"><div><span class="title">${esc(l.name)}</span><span class="sub">${esc(l.next)}</span></div><div>${esc(l.value)}</div><div><span class="chip">${esc(l.stage)}</span></div><div>Owner: Hamza</div><button class="miniButton" data-convert-lead="${l.id}">Convert</button></div>`).join('')}</div></article>`}
function clientsReviews(){return `<article class="card sectionCard">${sectionTitle('Reviews','Client feedback and approval state.')}<div class="listCard">${state.reviews.map(r=>`<div class="listRow"><div><span class="title">${esc(r.name)}</span><span class="sub">${esc(r.client)}</span></div><div>${esc(r.age)}</div><div><span class="chip ${statusKind(r.status)}">${esc(r.status)}</span></div><div>Secure review</div><button class="miniButton" data-review="${r.id}">${r.status==='Approved'?'Reopen':'Approve'}</button></div>`).join('')}</div></article>`}
function clientsPortal(){return `<div class="grid twoCol"><article class="card sectionCard">${sectionTitle('Client portal','Secure project-facing information for clients.')}<div class="statusLine"><span class="statusDot"></span><b>Portal foundation active</b></div><p style="font-size:12px;color:var(--muted)">Projects, files, reviews, documents and invoices can be presented from one client context. This RC9 V0.13 interface stores portal settings locally until the production backend is connected.</p><button class="primary" id="copyPortalLink">Copy sample portal link</button></article><article class="card sectionCard">${sectionTitle('Portal visibility','What clients can see.')}<div class="contextBlock"><b>Projects</b><span>Active project progress</span></div><div class="contextBlock"><b>Reviews</b><span>Approval requests and comments</span></div><div class="contextBlock"><b>Invoices</b><span>Open balances and payment state</span></div></article></div>`}
function clients(){const tab=state.tabs.clients;const body=tab==='leads'?clientsLeads():tab==='reviews'?clientsReviews():tab==='portal'?clientsPortal():clientsMain();return `<div class="surfaceToolbar">${tabs('clients',[['clients','Clients'],['leads','Leads'],['reviews','Reviews'],['portal','Portal']])}<button class="primary" data-create="client">+ Client</button></div>${body}`}

function documentsList(){return `<div class="grid docGrid">${state.documents.map(d=>`<article class="card docCard" data-open-doc="${d.id}"><div class="projectMark">D</div><h4>${esc(d.title)}</h4><p>${esc(d.project)} · ${esc(d.client)}</p><span>${esc(d.updated)}</span></article>`).join('')}</div>`}
function documentEditor(doc=state.documents[0]){return `<div class="editorShell"><article class="card editor"><input id="docTitle" value="${esc(doc.title)}" aria-label="Document title"><div class="editorMeta">Project: ${esc(doc.project)} · Client: ${esc(doc.client)} · Owner: ${esc(doc.owner)}</div><div class="editorBody" id="docBody" contenteditable="true">${doc.body}</div><div class="editorActions"><button class="secondary" data-tab-view="documents" data-tab="documents">Back to documents</button><button class="primary" data-save-doc="${doc.id}">Save document</button></div></article><aside class="card contextPanel"><h3>Document context</h3><div class="contextBlock"><b>Project</b><span>${esc(doc.project)}</span></div><div class="contextBlock"><b>Client</b><span>${esc(doc.client)}</span></div><div class="contextBlock"><b>Related files</b><span>${state.files.filter(f=>f.project===doc.project).length} project assets</span></div><div class="contextBlock"><b>Open tasks</b><span>${state.tasks.filter(t=>t.project===doc.project&&!t.done).length} tasks</span></div><button class="primary" style="width:100%" id="askFromDoc">✦ Ask about this document</button></aside></div>`}
function documentsKnowledge(){return `<article class="card sectionCard">${sectionTitle('Knowledge','Team knowledge organized by topic.','<button class="primary" data-create="document">+ Knowledge page</button>')}<div class="grid docGrid"><article class="card docCard"><div class="projectMark">K</div><h4>Client Operations</h4><p>Intake, reviews, delivery and relationship standards.</p></article><article class="card docCard"><div class="projectMark">K</div><h4>Creative Standards</h4><p>Brand, export and file organization practices.</p></article><article class="card docCard"><div class="projectMark">K</div><h4>Business Playbook</h4><p>Pricing, estimates, invoices and profitability.</p></article></div></article>`}
function documentsTemplates(){return `<article class="card sectionCard">${sectionTitle('Templates','Reusable starting points for repeatable work.')}<div class="grid docGrid"><article class="card docCard" data-template="Creative Brief"><div class="projectMark">T</div><h4>Creative Brief</h4><p>Objectives, audience, deliverables and references.</p></article><article class="card docCard" data-template="Project Kickoff"><div class="projectMark">T</div><h4>Project Kickoff</h4><p>Scope, owners, dates, dependencies and next steps.</p></article><article class="card docCard" data-template="Delivery Checklist"><div class="projectMark">T</div><h4>Delivery Checklist</h4><p>Final files, client approval and invoice closeout.</p></article></div></article>`}
function documents(){const tab=state.tabs.documents;const body=tab==='knowledge'?documentsKnowledge():tab==='templates'?documentsTemplates():documentsList();return `<div class="surfaceToolbar">${tabs('documents',[['documents','Documents'],['knowledge','Knowledge'],['templates','Templates']])}<button class="primary" data-create="document">+ Document</button></div>${body}`}

function filesTable(rows){return `<div class="tableWrap"><table class="dataTable"><thead><tr><th>Name</th><th>Project</th><th>Version</th><th>Review</th><th>Updated</th></tr></thead><tbody>${rows.map(f=>`<tr><td><div class="fileName"><span class="fileIcon">${esc(f.name.split('.').pop().slice(0,3).toUpperCase())}</span><strong>${esc(f.name)}</strong></div></td><td>${esc(f.project)}</td><td>${esc(f.version)}</td><td><span class="chip ${statusKind(f.review)}">${esc(f.review)}</span></td><td>${esc(f.updated)}</td></tr>`).join('')}</tbody></table></div>`}
function files(){let rows=state.files;const tab=state.tabs.files;if(tab==='versions')rows=rows.filter(f=>f.group==='versions');if(tab==='delivery')rows=rows.filter(f=>f.group==='delivery');if(tab==='connected')rows=rows.filter(f=>f.project!=='Unassigned');return `<div class="surfaceToolbar">${tabs('files',[['all','All files'],['versions','Versions'],['delivery','Delivery'],['connected','Connected']])}<button class="primary" id="uploadFiles">Upload files</button></div><div class="fileGrid"><article class="card sectionCard">${sectionTitle(tab==='delivery'?'Delivery files':tab==='versions'?'Version groups':'Smart files','Project-aware version, review and delivery state.')} ${filesTable(rows)}</article><aside class="card insight">${sectionTitle('File intelligence','Detected automatically.')}<div class="insightItem"><i>☁</i><div><b>Google Drive cloud storage</b><p>Authenticated workspace files are stored in the connected Qanteak Drive structure.</p></div></div><div class="insightItem"><i>V</i><div><b>Version-aware</b><p>New versions stay grouped through their logical file id.</p></div></div><div class="insightItem"><i>🔒</i><div><b>Workspace isolated</b><p>File metadata is protected by authenticated workspace access.</p></div></div></aside></div>`}

function businessOverview(){const revenue=state.invoices.filter(i=>i.status==='Paid').reduce((a,b)=>a+calcInvoice(b).total,0);const outstanding=state.invoices.filter(i=>i.status!=='Paid').reduce((a,b)=>a+calcInvoice(b).total,0);const exp=state.expenses.reduce((a,b)=>a+b.amount,0);const net=revenue-exp;return `<div class="grid moneyGrid"><article class="card moneyCard"><span>Paid revenue</span><b>${money(revenue)}</b><p>Paid invoices in this workspace</p></article><article class="card moneyCard"><span>Outstanding</span><b>${money(outstanding)}</b><p>${state.invoices.filter(i=>i.status!=='Paid').length} open invoices</p></article><article class="card moneyCard"><span>Expenses</span><b>${money(exp)}</b><p>Tracked business expenses</p></article><article class="card moneyCard"><span>Net position</span><b>${money(net)}</b><p>Paid revenue minus tracked expenses</p></article></div><article class="card sectionCard">${sectionTitle('Invoices','Payments, reminders and project connection.')}${invoiceTable()}</article><article class="card sectionCard">${sectionTitle('Project profitability','Profitability appears as invoice and expense data is linked to projects.')}<div class="empty">${state.projects.length?'Link invoices and expenses to projects to calculate margins.':'Create a project to start tracking profitability.'}</div></article>`}
function businessInvoices(){return `<article class="card sectionCard">${sectionTitle('Invoices','Create, track and update payment state.','<button class="primary" data-create="invoice">+ Invoice</button>')}${invoiceTable()}</article>`}
function businessEstimates(){return `<article class="card sectionCard">${sectionTitle('Estimates','Proposals and estimates before invoicing.')}<div class="listCard">${state.estimates.map(e=>`<div class="listRow"><div><span class="title">${esc(e.number)}</span><span class="sub">${esc(e.client)}</span></div><div>${money(e.amount)}</div><div><span class="chip">${esc(e.status)}</span></div><div>Owner: Hamza</div><button class="miniButton" data-estimate-open="${e.id}">Open</button></div>`).join('')}</div></article>`}
function businessExpenses(){return `<article class="card sectionCard">${sectionTitle('Expenses','Tracked costs connected to business reporting.','<button class="primary" data-create="expense">+ Expense</button>')}<div class="tableWrap"><table class="dataTable"><thead><tr><th>Expense</th><th>Category</th><th>Amount</th><th>Date</th></tr></thead><tbody>${state.expenses.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.category)}</td><td>${money(x.amount)}</td><td>${esc(x.date)}</td></tr>`).join('')}</tbody></table></div></article>`}
function business(){const tab=state.tabs.business;const body=tab==='invoices'?businessInvoices():tab==='estimates'?businessEstimates():tab==='expenses'?businessExpenses():businessOverview();return `<div class="surfaceToolbar">${tabs('business',[['overview','Overview'],['invoices','Invoices'],['estimates','Estimates'],['expenses','Expenses']])}<button class="primary" data-create="invoice">+ Invoice</button></div>${body}`}

function automations(){return `<div class="surfaceToolbar"><div class="surfaceTitle"><h2>Automation engine</h2><p>WHEN something happens · IF conditions match · THEN perform actions.</p></div><button class="primary" data-create="automation">+ Automation</button></div><div class="grid overview"><article class="card kpiCard"><h3>Active automations</h3><p>Running across the workspace.</p><strong>${state.automations.filter(a=>a.on).length}</strong></article><article class="card kpiCard"><h3>Runs this month</h3><p>Successful rule executions.</p><strong>${state.automations.reduce((n,a)=>n+Number(a.runs||0),0)}</strong></article><article class="card kpiCard"><h3>Time saved</h3><p>Estimated manual work avoided.</p><strong>${(state.automations.reduce((n,a)=>n+Number(a.minutesSaved||0),0)/60).toFixed(1)}h</strong></article></div><article class="card sectionCard">${sectionTitle('Your automations','Rules connect projects, clients, files, reviews and finance.')} ${state.automations.map(a=>`<div class="automationRow"><i>${a.icon}</i><div><b>${esc(a.name)}</b><p>${esc(a.rule)}</p></div><button class="miniButton" data-run-auto="${a.id}">Run now</button><button class="toggle ${a.on?'on':''}" data-auto="${a.id}"></button></div>`).join('')}</article>`}

function settings(){const appearance=state.preferences?.appearance||'light';return `<div class="grid twoCol"><article class="card sectionCard">${sectionTitle('Appearance','Choose how Qanteak looks on this device.')}<div class="appearanceChoices"><button type="button" class="appearanceChoice ${appearance==='light'?'active':''}" data-appearance="light"><span class="appearancePreview lightPreview"></span><b>Light</b><small>White Qanteak logo</small></button><button type="button" class="appearanceChoice ${appearance==='dark'?'active':''}" data-appearance="dark"><span class="appearancePreview darkPreview"></span><b>Dark</b><small>White Qanteak logo</small></button><button type="button" class="appearanceChoice ${appearance==='system'?'active':''}" data-appearance="system"><span class="appearancePreview systemPreview"></span><b>System</b><small>Follow Windows appearance</small></button></div><p class="settingsHint">The sidebar logo changes automatically with the active appearance. You can also click the logo to toggle Light ↔ Dark.</p></article><article class="card sectionCard">${sectionTitle('Workspace settings','Qanteak OS RC9 V0.13 preferences and local workspace controls.')}<div class="contextBlock"><b>Typography</b><span>Medium, semibold and bold weights only. Readable desktop scale enabled.</span></div><div class="contextBlock"><b>Application identity</b><span>Qanteak OS · RC9 V0.13 · in-place RC9 upgrade path</span></div><div class="contextBlock"><b>Local workspace data</b><span>Changes made in this RC interface persist on this PC.</span></div><div class="formActions"><button class="secondary" id="resetWorkspace">Reset demo data</button></div></article><article class="card sectionCard settingsWide">${sectionTitle('Updates','Check GitHub Releases and install the next Qanteak RC update.')}<div class="updateStatusCard"><span class="statusDot" id="updateStatusDot"></span><div><b id="updateStatusTitle">Ready to check</b><span id="updateStatusText">Click Check for updates to contact the Qanteak release feed.</span></div></div><div class="formActions updateActions"><button class="primary" id="checkUpdates">Check for updates</button><button class="secondary" id="restartUpdate" hidden>Restart & Update</button></div></article></div>`}

const renderers={home,work,clients,documents,files,business,automations,settings};
function render(view=state.view){if(!renderers[view]||!meta[view])view='home';if(backendState?.session&&!canViewAppView(view))view='home';state.view=view;const [t,s]=meta[view];$('#pageTitle').textContent=t;$('#pageSubtitle').textContent=s;$('#aiContext').textContent=`Context: ${t}`;$('#content').innerHTML=renderers[view]();$$('.navItem[data-view]').forEach(n=>{const allowed=canViewAppView(n.dataset.view);n.hidden=!allowed;n.classList.toggle('active',n.dataset.view===view)});bindContent();save();if(innerWidth<821){$('#sidebar').classList.remove('mobileOpen');setScrim(false)}}
function canViewAppView(view){if(!backendState?.session)return true;if(view==='home'||view==='settings'||view==='automations')return true;if(view==='clients')return accessAllows('clients','view');if(view==='documents')return accessAllows('documents','view');if(view==='files')return accessAllows('files','view');if(view==='business')return accessAllows('business','view');if(view==='work')return accessAllows('projects','view')||accessAllows('tasks','view')||accessAllows('reviews','view');return true}
function navigate(view){if(!canViewAppView(view)){toast('Access restricted','This area is not included in your workspace permissions.');return}closeAll();render(view)}

function bindContent(){setTimeout(()=>{$$('[data-create]').forEach(b=>{const map={task:'tasks',project:'projects',review:'reviews',client:'clients',document:'documents',note:'documents',sheet:'documents',slide:'documents',invoice:'business',expense:'business',automation:'business'};const mod=map[b.dataset.create];if(mod&&!accessAllows(mod,'create')){b.hidden=true;b.dataset.permissionHidden='1'}})},0);
  $$('[data-task]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(x=>x.id===b.dataset.task);if(t){t.done=!t.done;save();render(state.view)}});
  $$('[data-view-jump]').forEach(b=>b.onclick=()=>render(b.dataset.viewJump));
  $$('[data-create]').forEach(b=>b.onclick=()=>{const map={task:'tasks',project:'projects',review:'reviews',client:'clients',document:'documents',note:'documents',sheet:'documents',slide:'documents',invoice:'business',expense:'business',automation:'business'};const mod=map[b.dataset.create];if(mod&&!requireAccess(mod,'create',b.dataset.create))return;openCreate(b.dataset.create)});
  $$('[data-tab-view]').forEach(b=>b.onclick=()=>{state.tabs[b.dataset.tabView]=b.dataset.tab;save();render(b.dataset.tabView)});
  $$('[data-open-project]').forEach(b=>b.onclick=()=>openProject(b.dataset.openProject));
  $$('[data-open-client]').forEach(b=>b.onclick=()=>openClient(b.dataset.openClient));
  $$('[data-open-doc]').forEach(b=>b.onclick=()=>openDocument(b.dataset.openDoc));
  $$('[data-auto]').forEach(b=>b.onclick=()=>{const a=state.automations.find(x=>x.id===b.dataset.auto);if(a){a.on=!a.on;save();render('automations');toast('Automation updated',`${a.name} is now ${a.on?'active':'paused'}.`,'good')}});
  $$('[data-run-auto]').forEach(b=>b.onclick=()=>{const a=state.automations.find(x=>x.id===b.dataset.runAuto);toast('Automation run',a?`${a.name} completed a local test run.`:'Automation run completed.','good')});
  $$('[data-convert-lead]').forEach(b=>b.onclick=()=>convertLead(b.dataset.convertLead));
  $$('[data-review]').forEach(b=>b.onclick=()=>{if(!requireAccess('reviews','edit','reviews'))return;const r=state.reviews.find(x=>x.id===b.dataset.review);if(r){r.status=r.status==='Approved'?'In review':'Approved';save();render('work');toast('Review updated',`${r.name}: ${r.status}`,'good')}});
  $$('[data-invoice-status]').forEach(b=>b.onclick=()=>{const i=state.invoices.find(x=>x.id===b.dataset.invoiceStatus);if(i){i.status=i.status==='Paid'?'Sent':i.status==='Sent'?'Overdue':'Paid';save();render('business');toast('Invoice updated',`${i.number} is now ${i.status}.`,'good')}});
  $$('[data-template]').forEach(b=>b.onclick=()=>openCreate('document',b.dataset.template));
  $$('[data-estimate-open]').forEach(b=>b.onclick=()=>{const e=state.estimates.find(x=>x.id===b.dataset.estimateOpen);if(e)toast('Estimate '+e.number,`${e.client} · ${money(e.amount)} · ${e.status}`,'good')});
  $$('[data-save-doc]').forEach(b=>b.onclick=()=>saveDocument(b.dataset.saveDoc));
  $('#askFromDoc')?.addEventListener('click',openAi);$('#openBriefAi')?.addEventListener('click',openAi);
  $('#uploadFiles')?.addEventListener('click',async()=>{if(window.qanteakDesktop?.pickFiles){const picked=await window.qanteakDesktop.pickFiles();if(picked?.length){picked.forEach(f=>state.files.unshift({id:uid(),name:f.name,path:f.path,project:'Unassigned',version:'New upload',review:'Needs sorting',updated:'Just now',group:'all'}));save();render('files');toast('Files added',`${picked.length} file${picked.length>1?'s':''} added to Smart Files.`,'good')}}else $('#filePicker').click()});
  $('#saveWorkView')?.addEventListener('click',()=>toast('View saved','Your current Work view was saved locally.','good'));
  $('#copyPortalLink')?.addEventListener('click',async()=>{const link='https://portal.qanteak.com/client/sample';try{await navigator.clipboard.writeText(link);toast('Portal link copied',link,'good')}catch{toast('Sample portal link',link)}});
  $('#resetWorkspace')?.addEventListener('click',()=>{if(confirm('Reset the local RC9 V0.13 demo workspace?')){localStorage.removeItem(DEVICE_STORAGE);location.reload()}});
  $('#checkUpdates')?.addEventListener('click',doUpdateCheck);$('#restartUpdate')?.addEventListener('click',()=>window.qanteakDesktop?.restartToUpdate());syncUpdateStatus();
}

function openDocument(id){state.tabs.documents='documents';render('documents');const d=state.documents.find(x=>x.id===id);if(d)$('#content').innerHTML=`<div class="surfaceToolbar">${tabs('documents',[['documents','Documents'],['knowledge','Knowledge'],['templates','Templates']])}<button class="primary" data-create="document">+ Document</button></div>${documentEditor(d)}`,bindContent()}
function saveDocument(id){const d=state.documents.find(x=>x.id===id);if(!d)return;d.title=$('#docTitle').value.trim()||d.title;d.body=$('#docBody').innerHTML;d.updated='Just now';save();toast('Document saved',`${d.title} was saved locally.`,'good')}
function convertLead(id){const l=state.leads.find(x=>x.id===id);if(!l)return;state.clients.push({id:uid(),name:l.name,company:l.name,email:'',value:Number(String(l.value).replace(/[^0-9]/g,''))||0,projects:0,outstanding:0,relationship:'New client'});state.leads=state.leads.filter(x=>x.id!==id);save();render('clients');toast('Lead converted',`${l.name} is now a client.`,'good')}

function projectDetailSection(p,tab){
  const tasks=state.tasks.filter(t=>t.project===p.name),files=state.files.filter(f=>f.project===p.name),invoices=state.invoices.filter(i=>i.project===p.name);
  if(tab==='tasks')return `<div class="detailSection"><h4>Tasks</h4>${tasks.length?taskRows(tasks):'<p>No linked tasks yet.</p>'}</div>`;
  if(tab==='files')return `<div class="detailSection"><h4>Files</h4>${files.length?filesTable(files):'<p>No linked files yet.</p>'}</div>`;
  if(tab==='financials')return `<div class="detailSection"><h4>Financials</h4><p>${invoices.length?invoices.map(i=>`${esc(i.number)} · ${money(i.amount)} · ${esc(i.status)}`).join('<br>'):'No linked invoices yet.'}</p></div>`;
  if(tab==='activity')return `<div class="detailSection"><h4>Activity</h4><p>Project progress is ${p.progress}%. Current stage: ${esc(p.status)}. Due: ${esc(p.due)}.</p></div>`;
  return `<div class="detailSection"><h4>Overview</h4><p>${esc(p.description)}</p><h4>Connected work</h4><p>${tasks.length} tasks · ${files.length} files · ${invoices.length} invoices · Client: ${esc(p.client)}</p><div class="progress"><i style="width:${p.progress}%"></i></div></div>`;
}
function openProject(id){const p=state.projects.find(x=>x.id===id);if(!p)return;$('#detailTitle').textContent=p.name;$('#detailSubtitle').textContent=`${p.client} · ${p.status}`;$('#detailBody').innerHTML=`<div class="detailGrid"><div class="detailMetric"><span>Progress</span><b>${p.progress}%</b></div><div class="detailMetric"><span>Due</span><b>${esc(p.due)}</b></div><div class="detailMetric"><span>Owner</span><b>${esc(p.owner)}</b></div></div><div class="tabs detailTabs">${['overview','tasks','files','financials','activity'].map((t,i)=>`<button class="tab ${i===0?'active':''}" data-project-detail="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="detailSection">${projectDetailSection(p,'overview')}</div>`;$$('[data-project-detail]').forEach(b=>b.onclick=()=>{$$('[data-project-detail]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#detailSection').innerHTML=projectDetailSection(p,b.dataset.projectDetail)});$('#detailModal').classList.add('open');setScrim(true)}
function clientDetailSection(c,tab){
  const ps=state.projects.filter(p=>p.client===c.name),files=state.files.filter(f=>ps.some(p=>p.name===f.project)),reviews=state.reviews.filter(r=>r.client===c.name),invoices=state.invoices.filter(i=>i.client===c.name);
  if(tab==='projects')return `<div class="detailSection"><h4>Projects</h4>${ps.length?ps.map(p=>`<p><b>${esc(p.name)}</b> · ${p.progress}% · ${esc(p.status)}</p>`).join(''):'<p>No active projects.</p>'}</div>`;
  if(tab==='files')return `<div class="detailSection"><h4>Files</h4>${files.length?filesTable(files):'<p>No linked files.</p>'}</div>`;
  if(tab==='reviews')return `<div class="detailSection"><h4>Reviews</h4>${reviews.length?reviews.map(r=>`<p><b>${esc(r.name)}</b> · ${esc(r.status)} · ${esc(r.age)}</p>`).join(''):'<p>No reviews.</p>'}</div>`;
  if(tab==='invoices')return `<div class="detailSection"><h4>Invoices</h4>${invoices.length?invoices.map(i=>`<p><b>${esc(i.number)}</b> · ${money(i.amount)} · ${esc(i.status)}</p>`).join(''):'<p>No invoices.</p>'}</div>`;
  if(tab==='portal')return `<div class="detailSection"><h4>Portal</h4><p>Client portal context is ready for ${esc(c.name)}. Production authentication and secure share links require the connected backend.</p></div>`;
  return `<div class="detailSection"><h4>Relationship</h4><p>${esc(c.company)} · ${esc(c.email||'No email yet')}</p><h4>Projects</h4><p>${ps.map(p=>esc(p.name)).join(' · ')||'No active projects'}</p></div>`;
}
function openClient(id){const c=state.clients.find(x=>x.id===id);if(!c)return;$('#detailTitle').textContent=c.name;$('#detailSubtitle').textContent=c.relationship;const ps=state.projects.filter(p=>p.client===c.name);$('#detailBody').innerHTML=`<div class="detailGrid"><div class="detailMetric"><span>Lifetime value</span><b>${money(c.value)}</b></div><div class="detailMetric"><span>Outstanding</span><b>${money(c.outstanding)}</b></div><div class="detailMetric"><span>Active projects</span><b>${ps.length}</b></div></div><div class="tabs detailTabs">${['overview','projects','files','reviews','invoices','portal'].map((t,i)=>`<button class="tab ${i===0?'active':''}" data-client-detail="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="detailSection">${clientDetailSection(c,'overview')}</div>`;$$('[data-client-detail]').forEach(b=>b.onclick=()=>{$$('[data-client-detail]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#detailSection').innerHTML=clientDetailSection(c,b.dataset.clientDetail)});$('#detailModal').classList.add('open');setScrim(true)}

function setScrim(force){const any=$('#notifications').classList.contains('open')||$('#aiPanel').classList.contains('open')||$('#command').classList.contains('open')||$('#modal').classList.contains('open')||$('#detailModal').classList.contains('open')||$('#sidebar').classList.contains('mobileOpen');$('#scrim').classList.toggle('open',force??any)}
function updateNotificationCount(){const unread=state.notifications.filter(n=>!n.read).length;$('#notificationCount').textContent=unread||'';$('#topNotifications b').style.display=unread?'block':'none'}
function openNotifications(){const list=$('#notificationList');list.innerHTML=state.notifications.map(n=>`<button class="notification" data-notification="${n.id}" style="width:100%;border:0;background:${n.read?'transparent':'#f8fbff'};text-align:left"><span class="dot"></span><div><b>${esc(n.title)}</b><span>${esc(n.body)}</span></div></button>`).join('');$$('[data-notification]',list).forEach(b=>b.onclick=()=>{const n=state.notifications.find(x=>x.id===b.dataset.notification);if(n){n.read=true;save();openNotifications()}});$('#notifications').classList.add('open');setScrim()}
function openAi(){$('#aiPanel').classList.add('open');$('#aiEdgeTab')?.classList.add('panelOpen');$('#aiEdgeTab i')?.classList.replace('fi-rr-angle-left','fi-rr-angle-right');setScrim();setTimeout(()=>$('#aiInput').focus(),30)}
function openCommand(){$('#command').classList.add('open');setScrim();renderCommands('');setTimeout(()=>$('#commandInput').focus(),30)}
function closeAll(){$('#notifications').classList.remove('open');$('#aiPanel').classList.remove('open');$('#aiEdgeTab')?.classList.remove('panelOpen');const edgeIcon=$('#aiEdgeTab i');if(edgeIcon){edgeIcon.classList.remove('fi-rr-angle-right');edgeIcon.classList.add('fi-rr-angle-left')}$('#command').classList.remove('open');$('#modal').classList.remove('open');$('#detailModal').classList.remove('open');$('#sidebar').classList.remove('mobileOpen');setScrim(false)}

function commandData(){return [
  {i:'＋',title:'Create project',sub:'Start a connected client project.',action:'create:project'},
  {i:'$',title:'Create invoice',sub:'Create an invoice from project context.',action:'create:invoice'},
  {i:'✓',title:'Show tasks',sub:'Open all current tasks.',action:'tab:work:tasks'},
  {i:'⚙',title:'Settings',sub:'Open workspace settings and updates.',action:'view:settings'},
  {i:'↻',title:'Check for updates',sub:'Open Settings and check the Qanteak release feed.',action:'update:check'},
  ...state.projects.map(p=>({i:'P',title:p.name,sub:`Project · ${p.progress}% · ${p.status}`,action:`project:${p.id}`})),
  ...state.clients.map(c=>({i:'C',title:c.name,sub:`Client · ${money(c.value)} value`,action:`client:${c.id}`})),
  ...state.documents.map(d=>({i:'D',title:d.title,sub:`Document · ${d.project}`,action:`doc:${d.id}`})),
  ...state.files.map(f=>({i:'F',title:f.name,sub:`File · ${f.project}`,action:'view:files'})),
  ...state.invoices.map(i=>({i:'$',title:`Invoice ${i.number}`,sub:`${money(i.amount)} · ${i.status}`,action:'view:business'}))
]}
function renderCommands(q){q=q.toLowerCase().trim();const r=commandData().filter(c=>!q||`${c.title} ${c.sub}`.toLowerCase().includes(q)).slice(0,20);$('#commandResults').innerHTML=`<div class="commandGroup">Search & actions</div>${r.length?r.map(c=>`<div class="commandItem" data-command="${esc(c.action)}"><i>${esc(c.i)}</i><div><b>${esc(c.title)}</b><span>${esc(c.sub)}</span></div><kbd>↵</kbd></div>`).join(''):'<div class="empty">No matching Qanteak objects.</div>'}`;$$('[data-command]').forEach(el=>el.onclick=()=>runCommand(el.dataset.command))}
function runCommand(action){$('#command').classList.remove('open');if(action==='update:check'){navigate('settings');setTimeout(doUpdateCheck,0)}else if(action.startsWith('create:'))openCreate(action.split(':')[1]);else if(action.startsWith('project:'))openProject(action.split(':')[1]);else if(action.startsWith('client:'))openClient(action.split(':')[1]);else if(action.startsWith('doc:'))openDocument(action.split(':')[1]);else if(action.startsWith('tab:')){const [,view,tab]=action.split(':');state.tabs[view]=tab;navigate(view)}else if(action.startsWith('view:'))navigate(action.split(':')[1]);setScrim()}

function openCreate(type,prefill=''){
  const configs={
    task:['New task','Create a task in the current workspace.',[['Task title','text'],['Project','text'],['Due','text']]],
    project:['New project','Create a connected project.',[['Project name','text'],['Client','text'],['Due date','text']]],
    client:['New client','Add a client relationship.',[['Client name','text'],['Email','email'],['Company','text']]],
    lead:['New lead','Add a sales opportunity.',[['Lead name','text'],['Value','text'],['Next step','text']]],
    document:['New document','Create a contextual document.',[['Document title','text'],['Project','text'],['Client','text']]],
    invoice:['New invoice','Create an invoice from project context.',[['Client','text'],['Project','text'],['Amount','number']]],
    expense:['New expense','Track a business cost.',[['Expense name','text'],['Category','text'],['Amount','number']]],
    automation:['New automation','Create a WHEN / IF / THEN rule.',[['Automation name','text'],['Trigger / rule','text'],['Action','text']]]
  };
  const c=configs[type]||configs.task;$('#modalTitle').textContent=c[0];$('#modalSubtitle').textContent=c[1];$('#modalForm').dataset.type=type;$('#modalForm').innerHTML=c[2].map((f,i)=>`<div class="field"><label>${f[0]}</label><input name="field${i}" type="${f[1]}" value="${i===0?esc(prefill):''}" ${i===0?'required':''}></div>`).join('')+`<div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Create</button></div>`;$('#modal').classList.add('open');$$('[data-close="modal"]').forEach(b=>b.onclick=closeAll);setScrim(true);setTimeout(()=>$('#modalForm input')?.focus(),30)
}
function createFromForm(form){const type=form.dataset.type;const v=[...new FormData(form).values()].map(x=>String(x).trim());if(type==='task')state.tasks.unshift({id:uid(),title:v[0],project:v[1]||'Unassigned',due:v[2]||'No due date',done:false});
  if(type==='project')state.projects.unshift({id:uid(),name:v[0],client:v[1]||'Internal',status:'Planning',progress:0,due:v[2]||'No due date',owner:currentUserName(),description:'New connected Qanteak project.'});
  if(type==='client')state.clients.unshift({id:uid(),name:v[0],email:v[1],company:v[2]||v[0],value:0,projects:0,outstanding:0,relationship:'New client'});
  if(type==='lead')state.leads.unshift({id:uid(),name:v[0],value:v[1]||'$0',stage:'New',next:v[2]||'Follow up'});
  if(type==='document')state.documents.unshift({id:uid(),title:v[0],project:v[1]||'Unassigned',client:v[2]||'Internal',owner:currentUserName(),updated:'Just now',body:'<h2>Start writing</h2><p>Add your notes, brief or knowledge here.</p>'});
  if(type==='invoice')state.invoices.unshift({id:uid(),number:'#'+(107+state.invoices.length),client:v[0]||'Client',project:v[1]||'Project',amount:Number(v[2])||0,status:'Draft',due:'Not sent'});
  if(type==='expense')state.expenses.unshift({id:uid(),name:v[0],category:v[1]||'Other',amount:Number(v[2])||0,date:'Today'});
  if(type==='automation')state.automations.unshift({id:uid(),icon:'↯',name:v[0],rule:`WHEN ${v[1]||'trigger'} → ${v[2]||'action'}`,on:true});
  save();closeAll();toast(`${type[0].toUpperCase()+type.slice(1)} created`,'Saved to this Qanteak workspace.','good');render(type==='task'||type==='project'?'work':type==='client'||type==='lead'?'clients':type==='document'?'documents':type==='invoice'||type==='expense'?'business':type==='automation'?'automations':state.view)
}

function aiReply(v){const q=v.toLowerCase();if(q.includes('overdue')||q.includes('invoice')){const o=state.invoices.filter(i=>i.status==='Overdue');return o.length?`${o.length} overdue invoice${o.length>1?'s':''}: ${o.map(i=>`${i.number} for ${i.client} (${money(i.amount)})`).join(', ')}.`:'There are no overdue invoices.'}if(q.includes('task')){const open=state.tasks.filter(t=>!t.done);return `You have ${open.length} open tasks. The next ones are ${open.slice(0,3).map(t=>t.title).join(', ')}.`}if(q.includes('project')){return `There are ${state.projects.length} active projects. ${state.projects.filter(p=>/review|delivery/i.test(p.status)).length} are in review or delivery stages.`}if(q.includes('client')){return `You have ${state.clients.length} active client records and ${state.leads.length} open leads.`}if(q.includes('today')||q.includes('focus')){const b=dailyBrief();return b.body}return `I searched the current ${meta[state.view][0]} workspace context. You can ask about tasks, projects, clients, invoices, overdue work, or what to focus on today.`}
function toast(title,msg,kind=''){const el=document.createElement('div');el.className=`toast ${kind}`;el.innerHTML=`<b>${esc(title)}</b><span>${esc(msg)}</span>`;$('#toastHost').append(el);setTimeout(()=>el.remove(),4000)}

let updateUi={state:'idle',title:'Ready to check',message:'Click Check for updates to contact the Qanteak release feed.',downloaded:false};
function syncUpdateStatus(){const title=$('#updateStatusTitle'),text=$('#updateStatusText'),dot=$('#updateStatusDot'),restart=$('#restartUpdate');if(title)title.textContent=updateUi.title;if(text)text.textContent=updateUi.message;if(dot)dot.className=`statusDot ${updateUi.state==='error'?'bad':updateUi.state==='checking'?'warn':''}`;if(restart)restart.hidden=!updateUi.downloaded}
function setUpdateStatus(state,title,message,downloaded=false){updateUi={state,title,message,downloaded};syncUpdateStatus()}
async function doUpdateCheck(){if(!window.qanteakDesktop){setUpdateStatus('error','Updater unavailable','Run the packaged Qanteak Windows app to check updates.');toast('Desktop updater unavailable','Run the packaged Qanteak Windows app to check updates.');return}setUpdateStatus('checking','Checking for updates…','Contacting the Qanteak GitHub release feed.');toast('Qanteak update','Checking for updates…');try{await window.qanteakDesktop.checkForUpdates()}catch(e){const message=e?.message||'Could not check for updates.';setUpdateStatus('error','Update check failed',message);toast('Update check failed',message)}}



/* ================= RC9 V0.13 FUNCTIONAL OVERRIDES ================= */
const localIso=d=>{const x=d instanceof Date?d:new Date(d);const y=x.getFullYear(),m=String(x.getMonth()+1).padStart(2,'0'),day=String(x.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};
const isoToday=()=>localIso(new Date());
const fmtDate=v=>{if(!v)return 'No due date';const d=new Date(v+'T12:00:00');return Number.isNaN(+d)?v:new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(d)};
function clientOptions(selected=''){return `<option value="">Choose client</option>${state.clients.map(c=>`<option value="${esc(c.name)}" ${c.name===selected?'selected':''}>${esc(c.name)}</option>`).join('')}<option value="Internal" ${selected==='Internal'?'selected':''}>Internal</option>`}
function projectOptions(client='',selected=''){const rows=state.projects.filter(p=>!client||client==='Internal'?true:p.client===client);return `<option value="">Choose project</option>${rows.map(p=>`<option value="${esc(p.name)}" ${p.name===selected?'selected':''}>${esc(p.name)}</option>`).join('')}`}
function invoiceItems(i){return Array.isArray(i?.items)&&i.items.length?i.items:[{description:'Creative services',qty:1,rate:Number(i?.amount)||0}]}
function calcInvoice(i){const items=invoiceItems(i);const subtotal=items.reduce((a,x)=>a+(Number(x.qty)||0)*(Number(x.rate)||0),0);const discount=Number(i.discount)||0;const tax=Number(i.tax)||0;const afterDiscount=subtotal*(1-discount/100);const total=afterDiscount*(1+tax/100);return {subtotal,discount,tax,total}}
function dailyBrief(){const open=state.tasks.filter(t=>!t.done);const waiting=state.reviews.filter(r=>r.status!=='Approved');const overdue=state.invoices.filter(i=>i.status==='Overdue');const next=open.slice(0,3).map(t=>t.title);return {headline:`${open.length} open tasks · ${waiting.length} reviews waiting · ${overdue.length} overdue invoices`,body:`Focus on ${next.length?next.join(', '):'your next active project'}. ${waiting.length?`${waiting.length} review${waiting.length>1?'s':''} need attention. `:''}${overdue.length?`${overdue.length} invoice${overdue.length>1?'s are':' is'} overdue.`:'Finance is clear.'}`}}

// normalize fields introduced in the RC9 workspace model without breaking older RC9 local data
state.members=Array.isArray(state.members)?state.members:[];
state.tasks=state.tasks.map(t=>{if(t.date)return t;const base=new Date();if(/tomorrow/i.test(t.due||''))base.setDate(base.getDate()+1);else if(!/today/i.test(t.due||''))return t;return {...t,date:localIso(base)}});
state.notifications=state.notifications.map((n,i)=>({...n,category:n.category||(['Review','Finance','Urgent','Files'][i%4])}));
state.reviews=state.reviews.map((r,i)=>({...r,project:r.project||state.projects.find(p=>p.client===r.client)?.name||'Unassigned',due:r.due||isoToday()}));
state.documents=state.documents.map(d=>({...d,type:d.type||'doc'}));
state.invoices=state.invoices.map(i=>({...i,number:String(i.number||'').startsWith('#QTK-')?i.number:`#QTK-${String(i.number||'').replace(/\D/g,'')||Math.floor(2000+Math.random()*8000)}`,items:invoiceItems(i),discount:Number(i.discount)||0,tax:Number(i.tax)||0}));
state.clients=state.clients.map(c=>({...c,logo:c.logo||''}));
state.preferences={appearance:'light',workspaceName:'Qanteak Workspace',timezone:'Local',weekStarts:'Monday',notifyDesktop:true,notifyFinance:true,notifyReviews:true,...state.preferences};
persistDeviceState();

home=function(){
  const d=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(new Date());
  const outstanding=state.invoices.filter(i=>i.status!=='Paid').reduce((a,b)=>a+calcInvoice(b).total,0);
  const openTasks=state.tasks.filter(t=>!t.done).length;
  const brief=dailyBrief();
  return `<div class="welcome"><div><h2>Good morning, ${esc(currentUserName())}.</h2><p>Live workspace summary based on your authenticated Qanteak data.</p></div><div><span class="realtimePulse">Realtime</span><div class="dateChip">${d}</div></div></div>
  <div class="grid metrics">
    <article class="card metric"><div class="metricLabel"><span>Open tasks</span><i class="fi fi-rr-checkbox"></i></div><div class="metricValue"><strong>${openTasks}</strong><span class="chip good">Live</span></div><p>Updates as tasks are created or completed.</p></article>
    <article class="card metric"><div class="metricLabel"><span>Pending reviews</span><i class="fi fi-rr-star"></i></div><div class="metricValue"><strong>${state.reviews.filter(r=>r.status!=='Approved').length}</strong><span class="chip warn">Review</span></div><p>Approval requests across Work.</p></article>
    <article class="card metric"><div class="metricLabel"><span>Outstanding</span><i class="fi fi-rr-coins"></i></div><div class="metricValue"><strong>${money(outstanding)}</strong><span class="chip bad">Finance</span></div><p>All unpaid invoice totals.</p></article>
    <article class="card metric"><div class="metricLabel"><span>Active projects</span><i class="fi fi-rr-briefcase"></i></div><div class="metricValue"><strong>${state.projects.length}</strong><span class="chip good">Current</span></div><p>Client and internal projects.</p></article>
  </div>
  <div class="grid dashboard"><div class="stack">
    <article class="card sectionCard">${sectionTitle('Current projects','Status, progress and next action.','<button class="textButton" data-view-jump="work">View all</button>')}${projectRows()}</article>
    <article class="card sectionCard">${sectionTitle('Interactive calendar','Click any day to add a task or review.','<button class="textButton" data-tab-jump="calendar">Open calendar</button>')}${calendarMini()}</article>
  </div><div class="stack">
    <article class="card sectionCard">${sectionTitle('Today','Your live task queue.','<button class="textButton" data-create="task">Add task</button>')}<div id="taskList">${taskRows(state.tasks.slice(0,6))}</div></article>
    <article class="card aiCard"><div class="aiTop"><small><i class="fi fi-rr-sparkles"></i> Qanteak AI daily brief · live</small><h3>${esc(brief.headline)}</h3><p>${esc(brief.body)}</p></div><div class="aiBottom"><button class="textButton" id="openBriefAi">Ask Qanteak about my day →</button></div></article>
  </div></div>`
}

let homeCalendarOffset=0;
function calendarMini(){
  const base=new Date();base.setDate(1);base.setMonth(base.getMonth()+homeCalendarOffset);
  const year=base.getFullYear(),month=base.getMonth();
  const weekStartsMonday=(state.preferences?.weekStarts||'Monday')==='Monday';
  const weekDays=weekStartsMonday?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  const firstDay=new Date(year,month,1).getDay();
  const offset=weekStartsMonday?(firstDay+6)%7:firstDay;
  const gridStart=new Date(year,month,1-offset);
  const today=isoToday();
  const cells=[];
  for(let i=0;i<42;i++){
    const d=new Date(gridStart);d.setDate(gridStart.getDate()+i);const iso=localIso(d);
    const tasks=state.tasks.filter(t=>t.date===iso&&!t.done);const reviews=state.reviews.filter(r=>r.due===iso&&r.status!=='Approved');
    const outside=d.getMonth()!==month;
    cells.push(`<button class="homeCalCell ${outside?'outside':''} ${iso===today?'today':''}" data-calendar-date="${iso}" type="button" title="${tasks.length} task${tasks.length===1?'':'s'} · ${reviews.length} review${reviews.length===1?'':'s'}"><span class="homeCalDate">${d.getDate()}</span><span class="homeCalDots">${tasks.length?'<i class="taskDot"></i>':''}${reviews.length?'<i class="reviewDot"></i>':''}</span>${(tasks.length+reviews.length)>2?`<small>${tasks.length+reviews.length}</small>`:''}</button>`)
  }
  const label=new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(base);
  return `<div class="homeCalToolbar"><div><b>${esc(label)}</b><span>${state.tasks.filter(t=>t.date?.startsWith(`${year}-${String(month+1).padStart(2,'0')}`)&&!t.done).length} open tasks this month</span></div><div class="homeCalNav"><button type="button" data-home-cal-nav="prev" aria-label="Previous month">‹</button><button type="button" data-home-cal-nav="today">Today</button><button type="button" data-home-cal-nav="next" aria-label="Next month">›</button></div></div><div class="homeCalWeekdays">${weekDays.map(x=>`<span>${x}</span>`).join('')}</div><div class="homeCalMonth">${cells.join('')}</div><div class="homeCalLegend"><span><i class="taskDot"></i> Task</span><span><i class="reviewDot"></i> Review</span><span>Click any date to add an item</span></div>`
}

function workReviews(){return `<article class="card sectionCard">${sectionTitle('Reviews','Reviews now live in Work, beside the projects and tasks they belong to.','<button class="primary" data-create="review"><i class="fi fi-rr-plus"></i> Review</button>')}<div class="listCard">${state.reviews.map(r=>`<div class="listRow"><div><span class="title">${esc(r.name)}</span><span class="sub">${esc(r.client)} · ${esc(r.project)}</span></div><div>${fmtDate(r.due)}</div><div><span class="chip ${statusKind(r.status)}">${esc(r.status)}</span></div><div>Client review</div><button class="miniButton" data-review="${r.id}">${r.status==='Approved'?'Reopen':'Approve'}</button></div>`).join('')}</div></article>`}
workCalendar=function(){const now=new Date();const year=now.getFullYear(),month=now.getMonth();const first=new Date(year,month,1),start=new Date(year,month,1-first.getDay());const cells=[];for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const iso=d.toISOString().slice(0,10);const taskEvents=state.tasks.filter(t=>t.date===iso);const reviewEvents=state.reviews.filter(r=>r.due===iso);cells.push(`<div class="calendarCell ${d.getMonth()!==month?'muted':''}" data-calendar-date="${iso}"><div class="calendarDate">${d.getDate()}</div>${taskEvents.slice(0,3).map(t=>`<div class="calendarEvent">${esc(t.title)}</div>`).join('')}${reviewEvents.slice(0,2).map(r=>`<div class="calendarEvent review">${esc(r.name)}</div>`).join('')}</div>`)}return `<article class="card sectionCard"><div class="calendarToolbar"><div><h3>${new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(now)}</h3><p class="sub">Click a date to add a task or review.</p></div><div class="calendarToolbarActions"><button class="secondary" data-create="task">+ Task</button><button class="secondary" data-create="review">+ Review</button></div></div><div class="calendarMonthWrap"><div class="calendarMonth">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="calendarDow">${x}</div>`).join('')}${cells.join('')}</div></div></article>`}
work=function(){const tab=state.tabs.work;const body=tab==='tasks'?workTasks():tab==='calendar'?workCalendar():tab==='reviews'?workReviews():tab==='timeline'?workTimeline():workProjects();return `<div class="surfaceToolbar">${tabs('work',[['projects','Projects'],['tasks','Tasks'],['calendar','Calendar'],['reviews','Reviews'],['timeline','Timeline']])}<button class="primary" data-create="project"><i class="fi fi-rr-plus"></i> Project</button></div>${body}`}

clientsMain=function(){return `<div class="grid overview"><article class="card kpiCard"><h3>Active clients</h3><p>Clients with current work.</p><strong>${state.clients.length}</strong></article><article class="card kpiCard"><h3>Client value</h3><p>Revenue from active relationships.</p><strong>${money(state.clients.reduce((a,b)=>a+b.value,0))}</strong></article><article class="card kpiCard"><h3>Open projects</h3><p>Work linked to clients.</p><strong>${state.projects.filter(p=>p.client!=='Internal').length}</strong></article></div><div class="grid clientGrid">${state.clients.map(c=>`<article class="card clientCard" data-open-client="${c.id}"><div class="clientHead">${c.logo?`<img class="clientLogo" src="${c.logo}" alt="">`:`<div class="projectMark">${esc(c.name.split(/\s+/).map(x=>x[0]).slice(0,2).join(''))}</div>`}<div><h4>${esc(c.name)}</h4><span>${esc(c.relationship)}</span></div></div><div class="clientStats"><div><b>${money(c.value)}</b><span>Lifetime value</span></div><div><b>${state.projects.filter(p=>p.client===c.name).length}</b><span>Projects</span></div><div><b>${money(c.outstanding)}</b><span>Outstanding</span></div></div></article>`).join('')}</div>`}
clients=function(){const tab=state.tabs.clients;const body=tab==='leads'?clientsLeads():tab==='portal'?clientsPortal():clientsMain();return `<div class="surfaceToolbar">${tabs('clients',[['clients','Clients'],['leads','Leads'],['portal','Portal']])}<button class="primary" data-create="client">+ Client</button></div>${body}`}

function docIcon(type){return type==='sheet'?'fi-rr-table-columns':type==='slide'?'fi-rr-presentation':type==='note'?'fi-rr-note-sticky':'fi-rr-document'}
documentsList=function(){return `<div class="surfaceToolbar"><div class="surfaceTitle"><h2>Create</h2><p>Documents, notes, sheets and slides all keep client + project context.</p></div><div class="topActions"><button class="secondary" data-create="note">+ Note</button><button class="secondary" data-create="sheet">+ Sheet</button><button class="secondary" data-create="slide">+ Slides</button><button class="primary" data-create="document">+ Doc</button></div></div><div class="grid docGrid">${state.documents.map(d=>`<article class="card docCard" data-open-doc="${d.id}"><div class="projectMark"><i class="fi ${docIcon(d.type)}"></i></div><span class="docTypeBadge">${esc(d.type)}</span><h4>${esc(d.title)}</h4><p>${esc(d.project)} · ${esc(d.client)}</p><span>${esc(d.updated)}</span></article>`).join('')}</div>`}
documents=function(){const tab=state.tabs.documents;const body=tab==='knowledge'?documentsKnowledge():tab==='templates'?documentsTemplates():documentsList();return `<div class="surfaceToolbar">${tabs('documents',[['documents','Documents'],['knowledge','Knowledge'],['templates','Templates']])}</div>${body}`}

filesTable=function(rows){return `<div class="tableWrap"><table class="dataTable"><thead><tr><th>Name</th><th>Project</th><th>Version</th><th>Review</th><th>Updated</th><th></th></tr></thead><tbody>${rows.map(f=>`<tr><td><div class="fileName"><span class="fileIcon">${esc(f.name.split('.').pop().slice(0,3).toUpperCase())}</span><strong>${esc(f.name)}</strong></div></td><td>${esc(f.project)}</td><td>${esc(f.version)}</td><td><span class="chip ${statusKind(f.review)}">${esc(f.review)}</span></td><td>${esc(f.updated)}</td><td><div class="fileActions"><button class="miniButton" data-file-download="${f.id}" ${f.path?'':'disabled'}><i class="fi fi-rr-download"></i> Download</button></div></td></tr>`).join('')}</tbody></table></div>`}

function invoiceTable(){return `<div class="tableWrap"><table class="dataTable"><thead><tr><th>Invoice</th><th>Client</th><th>Project</th><th>Total</th><th>Status</th><th>Due</th><th></th></tr></thead><tbody>${state.invoices.map(i=>{const total=calcInvoice(i).total;return `<tr><td><strong>${esc(i.number)}</strong></td><td>${esc(i.client)}</td><td>${esc(i.project)}</td><td>${money(total)}</td><td><span class="chip ${statusKind(i.status)}">${esc(i.status)}</span></td><td>${esc(i.due||'Not sent')}</td><td><button class="miniButton" data-open-invoice="${i.id}">Open</button></td></tr>`}).join('')}</tbody></table></div>`}

settings=function(){const appearance=state.preferences.appearance||'light';return `<div class="settingsNav"><button class="tab active">General</button><button class="tab">Workspace</button><button class="tab">Members & access</button><button class="tab">Notifications</button><button class="tab">Updates</button></div><div class="grid twoCol">
<article class="card sectionCard">${sectionTitle('Appearance','Theme and brand treatment on this device.')}<div class="appearanceChoices"><button type="button" class="appearanceChoice ${appearance==='light'?'active':''}" data-appearance="light"><span class="appearancePreview lightPreview"></span><b>Light</b><small>White Qanteak logo</small></button><button type="button" class="appearanceChoice ${appearance==='dark'?'active':''}" data-appearance="dark"><span class="appearancePreview darkPreview"></span><b>Dark</b><small>White Qanteak logo</small></button><button type="button" class="appearanceChoice ${appearance==='system'?'active':''}" data-appearance="system"><span class="appearancePreview systemPreview"></span><b>System</b><small>Follow Windows</small></button></div><p class="settingsHint">Clicking the sidebar logo also toggles Light ↔ Dark.</p></article>
<article class="card sectionCard">${sectionTitle('General','Device and workspace behavior.')}<div class="formGrid"><div class="field"><label>Workspace name</label><input id="prefWorkspaceName" value="${esc(state.preferences.workspaceName)}"></div><div class="field"><label>Week starts</label><select id="prefWeekStarts"><option ${state.preferences.weekStarts==='Monday'?'selected':''}>Monday</option><option ${state.preferences.weekStarts==='Sunday'?'selected':''}>Sunday</option></select></div><div class="field span2"><label>Timezone</label><input id="prefTimezone" value="${esc(state.preferences.timezone)}"></div></div><div class="formActions"><button class="primary" id="saveGeneralSettings">Save settings</button></div></article>
<article class="card sectionCard settingsWide">${sectionTitle('Members & access','Add or remove members, assign roles, and scope access.','<button class="primary" data-create="member">+ Member</button>')}<div>${state.members.map(m=>`<div class="memberRow"><div><b>${esc(m.name)}</b><span class="sub">${esc(m.email)}</span></div><select data-member-role="${m.id}"><option ${m.role==='Owner'?'selected':''}>Owner</option><option ${String(m.role||'').toLowerCase()==='admin'?'selected':''}>Admin</option><option ${String(m.role||'').toLowerCase()==='editor'?'selected':''}>Editor</option><option ${String(m.role||'').toLowerCase()==='viewer'?'selected':''}>Viewer</option></select><select data-member-access="${m.id}"><option ${m.access?.includes('Everything')?'selected':''}>Everything</option><option ${m.access?.includes('Clients')?'selected':''}>Work, Clients, Documents</option><option ${m.access?.includes('Files')&&!m.access?.includes('Clients')?'selected':''}>Work, Files</option><option ${m.access?.includes('Business')?'selected':''}>Business only</option></select><button class="miniButton" data-member-remove="${m.id}" ${m.role==='Owner'?'disabled':''}>Remove</button></div>`).join('')}</div></article>
<article class="card sectionCard">${sectionTitle('Notifications','Choose which desktop categories should interrupt you.')}<label class="contextBlock"><b>Desktop notifications</b><input type="checkbox" id="prefNotifyDesktop" ${state.preferences.notifyDesktop?'checked':''}></label><label class="contextBlock"><b>Finance alerts</b><input type="checkbox" id="prefNotifyFinance" ${state.preferences.notifyFinance?'checked':''}></label><label class="contextBlock"><b>Review alerts</b><input type="checkbox" id="prefNotifyReviews" ${state.preferences.notifyReviews?'checked':''}></label></article>
<article class="card sectionCard">${sectionTitle('Data & safety','Local workspace controls for this RC.')}<div class="contextBlock"><b>Local persistence</b><span>Projects, tasks, invoices, docs and settings persist on this PC.</span></div><div class="contextBlock"><b>Release identity</b><span>Qanteak OS RC9 V0.20 · 1.0.0-rc.9.20</span></div><div class="formActions"><button class="secondary" id="resetWorkspace">Reset local data</button></div></article>
<article class="card sectionCard settingsWide">${sectionTitle('Updates','Check GitHub Releases and install the next Qanteak RC update.')}<div class="updateStatusCard"><span class="statusDot" id="updateStatusDot"></span><div><b id="updateStatusTitle">Ready to check</b><span id="updateStatusText">Click Check for updates to contact the Qanteak release feed.</span></div></div><div class="formActions updateActions"><button class="primary" id="checkUpdates">Check for updates</button><button class="secondary" id="restartUpdate" hidden>Restart & Update</button></div></article></div>`}

openCreate=function(type,prefill=''){
  const typeMap={note:'note',sheet:'sheet',slide:'slide'}; const docType=typeMap[type]||'doc'; if(typeMap[type])type='document';
  $('#modalForm').dataset.type=type;$('#modalForm').dataset.docType=docType;
  const today=typeof prefill==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(prefill)?prefill:'';
  if(type==='task'||type==='review'){
    $('#modalTitle').textContent=type==='task'?'New task':'New review';$('#modalSubtitle').textContent='Choose the client first; projects will filter automatically.';
    $('#modalForm').innerHTML=`<div class="formGrid"><div class="field span2"><label>${type==='task'?'Task title':'Review title'}</label><input name="title" required></div><div class="field"><label>Client</label><select name="client" id="createClient">${clientOptions()}</select></div><div class="field"><label>Project</label><select name="project" id="createProject">${projectOptions()}</select></div><div class="field"><label>Date</label><input name="date" type="date" value="${today||isoToday()}" required></div><div class="field"><label>${type==='review'?'Status':'Priority'}</label><select name="extra">${type==='review'?'<option>Waiting</option><option>In review</option><option>Approved</option>':'<option>Normal</option><option>High</option><option>Urgent</option>'}</select></div></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Create</button></div>`;
  } else if(type==='project'){
    $('#modalTitle').textContent='New project';$('#modalSubtitle').textContent='Create a project and connect it to an existing client.';$('#modalForm').innerHTML=`<div class="formGrid"><div class="field span2"><label>Project name</label><input name="title" required value="${esc(prefill)}"></div><div class="field"><label>Client</label><select name="client">${clientOptions()}</select></div><div class="field"><label>Due date</label><input name="date" type="date" value="${isoToday()}"></div><div class="field"><label>Status</label><select name="status"><option>Planning</option><option>In progress</option><option>Client review</option><option>Delivery</option></select></div><div class="field"><label>Owner</label><select name="owner">${state.members.map(m=>`<option>${esc(m.name)}</option>`).join('')}</select></div></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Create project</button></div>`;
  } else if(type==='document'){
    $('#modalTitle').textContent=`New ${docType==='doc'?'document':docType}`;$('#modalSubtitle').textContent='Choose client and project context before creating.';$('#modalForm').innerHTML=`<div class="formGrid"><div class="field span2"><label>Title</label><input name="title" required value="${esc(prefill)}"></div><div class="field"><label>Type</label><select name="docType"><option value="doc" ${docType==='doc'?'selected':''}>Document</option><option value="note" ${docType==='note'?'selected':''}>Note</option><option value="sheet" ${docType==='sheet'?'selected':''}>Sheet</option><option value="slide" ${docType==='slide'?'selected':''}>Slides</option></select></div><div class="field"><label>Client</label><select name="client" id="createClient">${clientOptions()}</select></div><div class="field span2"><label>Project</label><select name="project" id="createProject">${projectOptions()}</select></div></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Create</button></div>`;
  } else if(type==='invoice'){
    $('#modalTitle').textContent='New invoice';$('#modalSubtitle').textContent='Build a detailed invoice with line items, discount and tax.';$('#modalForm').innerHTML=`<div class="formGrid"><div class="field"><label>Client</label><select name="client" id="createClient" required>${clientOptions()}</select></div><div class="field"><label>Project</label><select name="project" id="createProject">${projectOptions()}</select></div><div class="field"><label>Invoice number</label><input name="number" value="#QTK-${2500+state.invoices.length+1}"></div><div class="field"><label>Due date</label><input name="date" type="date" value="${isoToday()}"></div></div><div class="field"><label>Line items</label><div class="lineItems" id="lineItems"></div><button type="button" class="secondary" id="addLine">+ Add line</button></div><div class="formGrid"><div class="field"><label>Discount %</label><input name="discount" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Tax %</label><input name="tax" type="number" min="0" step="0.01" value="0"></div></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Create invoice</button></div>`;addInvoiceLine();
  } else if(type==='member'){
    $('#modalTitle').textContent='Add member';$('#modalSubtitle').textContent='Create a local workspace member and assign access.';$('#modalForm').innerHTML=`<div class="formGrid"><div class="field"><label>Name</label><input name="title" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Role</label><select name="role"><option>Admin</option><option>Editor</option><option>Viewer</option></select></div><div class="field"><label>Access</label><select name="access"><option>Everything</option><option>Work, Clients, Documents</option><option>Work, Files</option><option>Business only</option></select></div></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Add member</button></div>`;
  } else {
    const simple={client:['New client','Client name','Email','Company'],lead:['New lead','Lead name','Value','Next step'],expense:['New expense','Expense name','Category','Amount'],automation:['New automation','Automation name','Trigger / rule','Action']}[type]||['Create','Title','Field','Value'];$('#modalTitle').textContent=simple[0];$('#modalSubtitle').textContent='Add this item to the current workspace.';$('#modalForm').innerHTML=`<div class="formGrid"><div class="field span2"><label>${simple[1]}</label><input name="title" required value="${esc(prefill)}"></div><div class="field"><label>${simple[2]}</label><input name="field2"></div><div class="field"><label>${simple[3]}</label><input name="field3"></div></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Create</button></div>`;
  }
  const client=$('#createClient'),project=$('#createProject');if(client&&project)client.addEventListener('change',()=>project.innerHTML=projectOptions(client.value));
  $('#addLine')?.addEventListener('click',addInvoiceLine);$('#modal').classList.add('open');$$('[data-close="modal"]').forEach(b=>b.onclick=closeAll);setScrim(true);setTimeout(()=>$('#modalForm input, #modalForm select')?.focus(),30)
}
function addInvoiceLine(item={description:'',qty:1,rate:0}){const host=$('#lineItems');if(!host)return;const row=document.createElement('div');row.className='lineItem';row.innerHTML=`<div class="field"><label>Description</label><input name="itemDescription" value="${esc(item.description)}" required></div><div class="field"><label>Qty</label><input name="itemQty" type="number" min="0" step="0.01" value="${item.qty}"></div><div class="field"><label>Rate</label><input name="itemRate" type="number" min="0" step="0.01" value="${item.rate}"></div><div class="lineTotal">${money((Number(item.qty)||0)*(Number(item.rate)||0))}</div><button type="button" class="removeLine">×</button>`;host.append(row);const recalc=()=>row.querySelector('.lineTotal').textContent=money((Number(row.querySelector('[name=itemQty]').value)||0)*(Number(row.querySelector('[name=itemRate]').value)||0));row.querySelectorAll('input').forEach(x=>x.addEventListener('input',recalc));row.querySelector('.removeLine').onclick=()=>row.remove()}

createFromForm=function(form){const type=form.dataset.type,fd=new FormData(form);if(type==='task'){state.tasks.unshift({id:uid(),title:String(fd.get('title')).trim(),client:String(fd.get('client')||''),project:String(fd.get('project')||'Unassigned'),date:String(fd.get('date')||''),due:fmtDate(String(fd.get('date')||'')),priority:String(fd.get('extra')||'Normal'),done:false})}
else if(type==='review'){state.reviews.unshift({id:uid(),name:String(fd.get('title')).trim(),client:String(fd.get('client')||''),project:String(fd.get('project')||'Unassigned'),due:String(fd.get('date')||isoToday()),status:String(fd.get('extra')||'Waiting'),age:'Just now'})}
else if(type==='project'){state.projects.unshift({id:uid(),name:String(fd.get('title')).trim(),client:String(fd.get('client')||'Internal'),status:String(fd.get('status')||'Planning'),progress:0,due:fmtDate(String(fd.get('date')||'')),owner:String(fd.get('owner')||currentUserName()),description:'New connected Qanteak project.'})}
else if(type==='document'){state.documents.unshift({id:uid(),title:String(fd.get('title')).trim(),type:String(fd.get('docType')||form.dataset.docType||'doc'),project:String(fd.get('project')||'Unassigned'),client:String(fd.get('client')||'Internal'),owner:currentUserName(),updated:'Just now',body:'<h2>Start writing</h2><p>Add your content here.</p>'})}
else if(type==='invoice'){const desc=fd.getAll('itemDescription'),qty=fd.getAll('itemQty'),rate=fd.getAll('itemRate');const items=desc.map((d,i)=>({description:String(d).trim(),qty:Number(qty[i])||0,rate:Number(rate[i])||0})).filter(x=>x.description);const inv={id:uid(),number:String(fd.get('number')||`#QTK-${2500+state.invoices.length+1}`),client:String(fd.get('client')||''),project:String(fd.get('project')||''),items,discount:Number(fd.get('discount'))||0,tax:Number(fd.get('tax'))||0,status:'Draft',due:fmtDate(String(fd.get('date')||''))};inv.amount=calcInvoice(inv).total;state.invoices.unshift(inv)}
else if(type==='member'){state.members.push({id:uid(),name:String(fd.get('title')).trim(),email:String(fd.get('email')).trim(),role:String(fd.get('role')),access:String(fd.get('access')).split(',').map(x=>x.trim())})}
else if(type==='client'){state.clients.unshift({id:uid(),name:String(fd.get('title')).trim(),email:String(fd.get('field2')||''),company:String(fd.get('field3')||fd.get('title')),value:0,projects:0,outstanding:0,relationship:'New client',logo:''})}
else if(type==='lead'){state.leads.unshift({id:uid(),name:String(fd.get('title')).trim(),value:String(fd.get('field2')||'$0'),stage:'New',next:String(fd.get('field3')||'Follow up')})}
else if(type==='expense'){state.expenses.unshift({id:uid(),name:String(fd.get('title')).trim(),category:String(fd.get('field2')||'Other'),amount:Number(fd.get('field3'))||0,date:'Today'})}
else if(type==='automation'){state.automations.unshift({id:uid(),icon:'↯',name:String(fd.get('title')).trim(),rule:`WHEN ${String(fd.get('field2')||'trigger')} → ${String(fd.get('field3')||'action')}`,on:true})}
save();closeAll();toast(`${type[0].toUpperCase()+type.slice(1)} created`,'Saved to this Qanteak workspace.','good');render(type==='task'||type==='project'||type==='review'?'work':type==='client'||type==='lead'?'clients':type==='document'?'documents':type==='invoice'||type==='expense'?'business':type==='automation'?'automations':type==='member'?'settings':state.view)}

function openInvoice(id){const i=state.invoices.find(x=>x.id===id);if(!i)return;const totals=calcInvoice(i);$('#detailTitle').textContent=`Invoice ${i.number}`;$('#detailSubtitle').textContent=`${i.client} · ${i.project} · ${i.status}`;$('#detailBody').innerHTML=`<div class="invoicePaper"><div class="invoicePaperHead"><div><h2>Invoice ${esc(i.number)}</h2><p>${esc(i.client)} · ${esc(i.project)}</p></div><div><b>Due</b><p>${esc(i.due||'Not sent')}</p></div></div><table><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Total</th></tr></thead><tbody>${invoiceItems(i).map(x=>`<tr><td>${esc(x.description)}</td><td>${x.qty}</td><td>${money(x.rate)}</td><td>${money((Number(x.qty)||0)*(Number(x.rate)||0))}</td></tr>`).join('')}</tbody></table><div class="invoiceSummary"><span>Subtotal</span><b>${money(totals.subtotal)}</b><span>Discount</span><b>${totals.discount}%</b><span>Tax</span><b>${totals.tax}%</b><span class="grand">Total</span><b class="grand">${money(totals.total)}</b></div></div><div class="formActions"><button class="secondary" data-edit-invoice="${i.id}"><i class="fi fi-rr-edit"></i> Edit</button><button class="secondary" data-invoice-status="${i.id}">Change status</button><button class="primary" data-pdf-invoice="${i.id}"><i class="fi fi-rr-download"></i> Download PDF</button></div>`;$('#detailModal').classList.add('open');setScrim(true);bindInvoiceDetail()}
function bindInvoiceDetail(){$('[data-edit-invoice]')?.addEventListener('click',e=>editInvoice(e.currentTarget.dataset.editInvoice));$('[data-pdf-invoice]')?.addEventListener('click',async e=>{const i=state.invoices.find(x=>x.id===e.currentTarget.dataset.pdfInvoice);if(!i)return;try{if(window.qanteakDesktop?.saveInvoicePdf){const r=await window.qanteakDesktop.saveInvoicePdf({...i,totals:calcInvoice(i)});toast(r?.ok?'Invoice PDF saved':'PDF not saved',r?.path||r?.message||'Done',r?.ok?'good':'')}else{window.print()}}catch(err){toast('PDF export failed',err.message||'Could not save PDF.')}});$('[data-invoice-status]')?.addEventListener('click',e=>{const i=state.invoices.find(x=>x.id===e.currentTarget.dataset.invoiceStatus);if(i){i.status=i.status==='Paid'?'Sent':i.status==='Sent'?'Overdue':'Paid';save();openInvoice(i.id)}})}
function editInvoice(id){const i=state.invoices.find(x=>x.id===id);if(!i)return;closeAll();openCreate('invoice');const form=$('#modalForm');form.dataset.editId=id;form.querySelector('[name=client]').value=i.client;form.querySelector('[name=client]').dispatchEvent(new Event('change'));form.querySelector('[name=project]').value=i.project;form.querySelector('[name=number]').value=i.number;form.querySelector('[name=discount]').value=i.discount||0;form.querySelector('[name=tax]').value=i.tax||0;$('#lineItems').innerHTML='';invoiceItems(i).forEach(addInvoiceLine);const oldSubmit=form.onsubmit;form.onsubmit=e=>{e.preventDefault();const fd=new FormData(form),desc=fd.getAll('itemDescription'),qty=fd.getAll('itemQty'),rate=fd.getAll('itemRate');i.client=String(fd.get('client'));i.project=String(fd.get('project'));i.number=String(fd.get('number'));i.discount=Number(fd.get('discount'))||0;i.tax=Number(fd.get('tax'))||0;i.items=desc.map((d,j)=>({description:String(d).trim(),qty:Number(qty[j])||0,rate:Number(rate[j])||0})).filter(x=>x.description);i.amount=calcInvoice(i).total;save();closeAll();render('business');toast('Invoice saved',`${i.number} details updated.`,'good');form.onsubmit=oldSubmit}}

openClient=function(id){const c=state.clients.find(x=>x.id===id);if(!c)return;$('#detailTitle').textContent=c.name;$('#detailSubtitle').textContent=c.relationship;const ps=state.projects.filter(p=>p.client===c.name);$('#detailBody').innerHTML=`<div class="clientHead">${c.logo?`<img class="clientLogo" src="${c.logo}" alt="">`:`<div class="projectMark">${esc(c.name.slice(0,2).toUpperCase())}</div>`}<div><h3>${esc(c.company)}</h3><p>${esc(c.email||'No email')}</p></div></div><div class="detailGrid"><div class="detailMetric"><span>Lifetime value</span><b>${money(c.value)}</b></div><div class="detailMetric"><span>Outstanding</span><b>${money(c.outstanding)}</b></div><div class="detailMetric"><span>Active projects</span><b>${ps.length}</b></div></div><div class="formActions"><button class="secondary" data-client-logo="${c.id}">Change logo</button><button class="primary" data-edit-client="${c.id}">Edit client info</button></div><div class="tabs detailTabs">${['overview','projects','files','invoices','portal'].map((t,i)=>`<button class="tab ${i===0?'active':''}" data-client-detail="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="detailSection">${clientDetailSection(c,'overview')}</div>`;$$('[data-client-detail]').forEach(b=>b.onclick=()=>{$$('[data-client-detail]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#detailSection').innerHTML=clientDetailSection(c,b.dataset.clientDetail)});$('[data-edit-client]').onclick=()=>editClient(c.id);$('[data-client-logo]').onclick=()=>{const picker=$('#clientLogoPicker');picker.dataset.clientId=c.id;picker.click()};$('#detailModal').classList.add('open');setScrim(true)}
function editClient(id){const c=state.clients.find(x=>x.id===id);if(!c)return;$('#modalTitle').textContent='Edit client';$('#modalSubtitle').textContent='Update client identity and relationship details.';$('#modalForm').dataset.type='clientEdit';$('#modalForm').innerHTML=`<div class="formGrid"><div class="field"><label>Name</label><input name="name" value="${esc(c.name)}" required></div><div class="field"><label>Company</label><input name="company" value="${esc(c.company)}"></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(c.email||'')}"></div><div class="field"><label>Relationship</label><input name="relationship" value="${esc(c.relationship||'')}"></div></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Save client</button></div>`;$('#detailModal').classList.remove('open');$('#modal').classList.add('open');setScrim(true);$('#modalForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget),old=c.name;c.name=String(fd.get('name')).trim();c.company=String(fd.get('company'));c.email=String(fd.get('email'));c.relationship=String(fd.get('relationship'));state.projects.forEach(p=>{if(p.client===old)p.client=c.name});state.invoices.forEach(i=>{if(i.client===old)i.client=c.name});state.reviews.forEach(r=>{if(r.client===old)r.client=c.name});save();closeAll();render('clients');toast('Client updated',`${c.name} was saved.`,'good')}}

openNotifications=function(filter='All'){const cats=['All',...new Set(state.notifications.map(n=>n.category||'General'))];$('#notificationFilters').innerHTML=cats.map(c=>`<button class="notificationFilter ${c===filter?'active':''}" data-notif-filter="${esc(c)}">${esc(c)}</button>`).join('');const rows=filter==='All'?state.notifications:state.notifications.filter(n=>(n.category||'General')===filter);$('#notificationList').innerHTML=rows.map(n=>`<button class="notification" data-notification="${n.id}" style="width:100%;border:0;background:${n.read?'transparent':'var(--soft)'};text-align:left"><span class="dot ${/urgent|finance/i.test(n.category||'')?'bad':''}"></span><div><span class="notificationCategory">${esc(n.category||'General')}</span><b>${esc(n.title)}</b><span>${esc(n.body)}</span></div></button>`).join('');$$('[data-notif-filter]').forEach(b=>b.onclick=()=>openNotifications(b.dataset.notifFilter));$$('[data-notification]').forEach(b=>b.onclick=()=>{const n=state.notifications.find(x=>x.id===b.dataset.notification);if(n){n.read=true;save();openNotifications(filter)}});$('#notifications').classList.add('open');setScrim()}


function openCalendarChoice(date){$('#modalTitle').textContent=`Add to ${fmtDate(date)}`;$('#modalSubtitle').textContent='Choose what you want to schedule on this date.';$('#modalForm').dataset.type='calendarChoice';$('#modalForm').innerHTML=`<div class="grid twoCol"><button type="button" class="card sectionCard" id="calendarAddTask" style="text-align:left"><i class="fi fi-rr-checkbox"></i><h3>Task</h3><p>Add a task with client and project context.</p></button><button type="button" class="card sectionCard" id="calendarAddReview" style="text-align:left"><i class="fi fi-rr-star"></i><h3>Review</h3><p>Schedule a review or approval request.</p></button></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button></div>`;$('#modal').classList.add('open');setScrim(true);$('#calendarAddTask').onclick=()=>openCreate('task',date);$('#calendarAddReview').onclick=()=>openCreate('review',date);$$('[data-close="modal"]').forEach(b=>b.onclick=closeAll)}

// extend content binding for V0.8 controls
