    <article class="card sectionCard homeBriefCard"><div class="briefHead"><div><i class="fi fi-rr-sparkles"></i><div><h3>Qanteak AI</h3><p>Daily Brief</p></div></div><button class="textButton" id="openBriefAi">Refresh / Ask</button></div><div class="briefSummary"><b>${esc(brief.headline)}</b><p>${esc(brief.body)}</p></div><div class="briefList">${open.slice(0,3).map(t=>`<div><i class="fi fi-rr-checkbox"></i><span><b>${esc(t.title)}</b><small>${esc(t.project)} · ${esc(t.due)}</small></span></div>`).join('')}${pending.slice(0,2).map(r=>`<div><i class="fi fi-rr-star"></i><span><b>${esc(r.name)}</b><small>${esc(r.client)} · ${esc(r.status)}</small></span></div>`).join('')}</div><button class="secondary fullWidth" id="openBriefAi2">Ask Qanteak about my day</button></article>
