backendState={configured:false,backend:'Local only',session:null,workspaces:[],workspaceId:state.preferences.cloudWorkspaceId||'',lastSync:null,error:'',security:null,busy:false,entitlement:null,revision:0,invites:[],realtime:false,remoteActivity:null,members:[],backups:[],connectivity:{online:navigator.onLine,latencyMs:null},offlineDirty:false,workspaceLoaded:false,cacheHydrated:false};
const sharedWorkspaceKeys=WORKSPACE_COLLECTIONS;
let cloudSyncTimer=null, suppressCloudSync=false;
function workspacePayload(){const out={};for(const k of sharedWorkspaceKeys)out[k]=structuredClone(state[k]||[]);return out}
function applyWorkspacePayload(payload){suppressCloudSync=true;const source=(payload&&typeof payload==='object')?payload:{};for(const k of sharedWorkspaceKeys)state[k]=Array.isArray(source[k])?structuredClone(source[k]):[];saveLocalOnly();backendState.cacheHydrated=true;persistWorkspaceCache();suppressCloudSync=false}
const saveLocalOnly=save;
save=function(){saveLocalOnly();persistWorkspaceCache();if(!suppressCloudSync){if(backendState?.cacheHydrated&&!backendState?.workspaceLoaded)backendState.offlineDirty=true;scheduleCloudSync()}};
function scheduleCloudSync(){if(!backendState.session||!backendState.workspaceId||!window.qanteakDesktop?.backendPush||backendState.workspaceLoaded!==true)return;if(!navigator.onLine||backendState.connectivity?.online===false){backendState.offlineDirty=true;return}clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(()=>pushWorkspaceSnapshot(false),1800)}
function mergeCollectionById(remote=[],local=[]){const map=new Map((remote||[]).map(x=>[String(x?.id||uid()),structuredClone(x)]));for(const item of (local||[])){const id=String(item?.id||uid());map.set(id,{...(map.get(id)||{}),...structuredClone(item)})}return [...map.values()]}
function mergeWorkspacePayload(remote,local){const out={};for(const k of sharedWorkspaceKeys)out[k]=mergeCollectionById(remote?.[k]||[],local?.[k]||[]);return out}
async function pushWorkspaceSnapshot(showToast=true,retry=true){if(!backendState.workspaceId||!backendState.session)return;const local=workspacePayload();try{backendState.busy=true;const row=await window.qanteakDesktop.backendPush(backendState.workspaceId,local,backendState.revision||0);backendState.revision=Number(row?.revision||backendState.revision+1);backendState.lastSync=row?.updated_at||new Date().toISOString();backendState.error='';if(showToast)toast('Workspace synced',`Cloud revision ${backendState.revision} is current.`,'good')}catch(e){const msg=e?.message||'Cloud sync failed.';if(retry&&/revision conflict|40001/i.test(msg)){try{const remote=await window.qanteakDesktop.backendPull(backendState.workspaceId);backendState.revision=Number(remote?.revision||0);const merged=mergeWorkspacePayload(remote?.snapshot||{},local);applyWorkspacePayload(merged);backendState.busy=false;return pushWorkspaceSnapshot(showToast,false)}catch(conflictErr){backendState.error=conflictErr?.message||msg}}else backendState.error=msg;if(showToast)toast('Sync needs attention',backendState.error||msg)}finally{backendState.busy=false;if(state.view==='settings')render('settings')}}
async function pullWorkspaceSnapshot(showToast=true){if(!backendState.workspaceId||!backendState.session)return false;const localBefore=workspaceSnapshotForCache();const hadLocalDirty=!!backendState.offlineDirty;try{backendState.busy=true;const row=await window.qanteakDesktop.backendPull(backendState.workspaceId);const remote=row?.snapshot||{};const next=hadLocalDirty?mergeWorkspacePayload(remote,localBefore):remote;applyWorkspacePayload(next);backendState.revision=Number(row?.revision||backendState.revision||0);backendState.lastSync=row?.updated_at||null;backendState.error='';backendState.workspaceLoaded=true;backendState.cacheHydrated=true;backendState.offlineDirty=hadLocalDirty;persistWorkspaceCache();if(hadLocalDirty)scheduleCloudSync();if(showToast)toast('Workspace loaded',row?`Cloud revision ${backendState.revision} loaded.`:'A clean authenticated workspace is ready.','good');return true}catch(e){backendState.workspaceLoaded=false;backendState.error=e?.message||'Could not load cloud workspace.';const restored=restoreWorkspaceCache();if(showToast)toast(restored?'Showing saved workspace':'Cloud load failed',restored?'Qanteak kept your last saved workspace on this PC and will retry the cloud connection.':backendState.error,restored?'good':'');return false}finally{backendState.busy=false;if(state.view==='settings')render('settings')}}
function updateProfileFromSession(){const profile=$('.profile');if(!profile)return;const strong=$('strong',profile),sub=$('span',profile),avatar=$('.avatar',profile);if(backendState.session?.user){const u=backendState.session.user;const name=u.user_metadata?.name||u.email?.split('@')[0]||'Qanteak user';if(strong)strong.textContent=name;if(sub)sub.textContent=backendState.workspaces.find(w=>w.id===backendState.workspaceId)?.name||'Cloud workspace';if(avatar)avatar.textContent=name.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}else{if(strong)strong.textContent='Local workspace';if(sub)sub.textContent='Not signed in';if(avatar)avatar.textContent='L'}}
function ownMembership(){return (backendState.members||[]).find(m=>m.user_id===backendState.session?.user?.id)||null}
function accessAllows(module,action='view'){const m=ownMembership();if(!backendState.session)return false;if(!m)return true;const role=String(m.role||'').toLowerCase();if(role==='owner'||role==='admin')return true;const a=m.access;if(Array.isArray(a))return a.includes('Everything')||a.includes(module)||a.includes(`${module}.${action}`)||a.includes(`${module}:${action}`);if(a&&typeof a==='object')return !!(a[module]?.all||a[module]?.[action]||a[module]===true);return false}
