async function initBackend(){
  if(!window.qanteakDesktop?.backendStatus)return;
  try{
    const status=await window.qanteakDesktop.backendStatus();
    backendState.configured=!!status?.configured;
    backendState.backend=status?.backend||'Local only';
    backendState.session=status?.session||null;
    if(backendState.session){
      backendState.entitlement=window.qanteakDesktop?.backendEntitlement?await window.qanteakDesktop.backendEntitlement():{allowed:true,status:'unknown',plan:'unknown'};
      backendState.workspaces=backendState.entitlement?.allowed?await window.qanteakDesktop.backendWorkspaces():[];
      if(!backendState.workspaceId||!backendState.workspaces.some(w=>w.id===backendState.workspaceId)){
        backendState.workspaceId=backendState.workspaces[0]?.id||'';
        state.preferences.cloudWorkspaceId=backendState.workspaceId;
        saveLocalOnly();
      }
      try{
        const remoteSettings=await window.qanteakDesktop.backendGetUserSettings();
        if(remoteSettings){
          state.preferences={...state.preferences,...(remoteSettings.preferences||{})};
          state.security={...state.security,...(remoteSettings.security||{})};
          state.privacy={...state.privacy,...(remoteSettings.privacy||{})};
        }
      }catch{}
    }
    updateProfileFromSession();
  }catch(e){
    backendState.error=e?.message||'Backend unavailable';
    updateProfileFromSession();
  }finally{
    if(state.view==='settings')render('settings');
  }
}
async function saveCloudUserSettings(){if(!backendState.session||!window.qanteakDesktop?.backendSaveUserSettings)return;try{await window.qanteakDesktop.backendSaveUserSettings({preferences:{language:state.preferences.language,currency:state.preferences.currency,dateFormat:state.preferences.dateFormat,timezone:state.preferences.timezone,weekStarts:state.preferences.weekStarts,onboardingComplete:!!state.preferences.onboardingComplete,workspaceName:state.preferences.workspaceName},security:state.security,privacy:state.privacy})}catch(e){backendState.error=e?.message||'Could not save cloud settings.'}}
