function openCloudUpload(){if(!backendState.session||!backendState.workspaceId){toast('Sign in required','Open an authenticated Qanteak workspace first.');return}if(!backendState.drive.configured){toast('Google Drive setup required','The cloud storage backend is ready, but Google OAuth credentials still need to be configured.');state.settingsTab='storage';render('settings');return}$('#modalTitle').textContent='Upload to Google Drive';$('#modalSubtitle').textContent='Choose the client and project context, then select files from this PC.';$('#modalForm').dataset.type='cloudfile';$('#modalForm').innerHTML=`<div class="formGrid"><div class="field"><label>Client</label><select name="client" id="cloudUploadClient">${clientOptions()}</select></div><div class="field"><label>Project</label><select name="project" id="cloudUploadProject">${projectOptions()}</select></div></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Choose files & upload</button></div>`;$('#modal').classList.add('open');setScrim(true);$('#cloudUploadClient')?.addEventListener('change',e=>{const p=$('#cloudUploadProject');if(p)p.innerHTML=projectOptions(e.target.value,'')})}

async function uploadCloudFiles(form){const fd=new FormData(form),client=String(fd.get('client')||''),project=String(fd.get('project')||'');const picked=await window.qanteakDesktop?.pickFiles?.();if(!picked?.length)return;closeAll();toast('Cloud upload started',`${picked.length} file${picked.length>1?'s':''} uploading to Google Drive…`);try{const result=await window.qanteakDesktop.backendDriveUpload({workspaceId:backendState.workspaceId,paths:picked.map(x=>x.path),clientRef:client||null,projectRef:project||null});await refreshDriveStorage(false);render('files');toast('Cloud upload complete',`${result?.files?.length||picked.length} file${picked.length>1?'s':''} stored in Google Drive.`,'good')}catch(e){toast('Cloud upload failed',e?.message||'Could not upload files to Google Drive.')}}

