function settingsStorage(){const d=backendState.drive;return `<div class="grid twoCol"><article class="card sectionCard">${sectionTitle('Google Drive cloud storage','File binaries live in the dedicated Qanteak Storage folder while Supabase stores access metadata.')}<div class="securityGrid">${statusBadge(!!backendState.session,backendState.session?'Authenticated':'Sign in required')}${statusBadge(!!d.configured,d.configured?'Google Drive connected':'Google OAuth setup required')}</div><div class="contextBlock"><b>Provider</b><span>${esc(d.provider||'Google Drive')}</span></div><div class="contextBlock"><b>Root folder</b><span>${esc(d.rootFolderId||'Qanteak Storage')}</span></div><div class="contextBlock"><b>Workspace files</b><span>${d.configured?`${d.files.length} cloud file record${d.files.length===1?'':'s'}`:'Backend function installed; credentials are the final connection step.'}</span></div><div class="formActions"><button class="secondary" data-drive-refresh>Refresh status</button><button class="primary" data-view-jump="files">Open Files</button></div></article><article class="card sectionCard">${sectionTitle('Storage security','Qanteak never exposes your master Google Drive account to workspace users.')}<div class="contextBlock"><b>Workspace isolation</b><span>Supabase membership checks are required before file metadata is returned.</span></div><div class="contextBlock"><b>Binary storage</b><span>Google Drive stores PSD, AI, video, PDF, Office and other file binaries.</span></div><div class="contextBlock"><b>Current setup</b><span>${d.configured?'Ready for uploads.':'Google OAuth client ID, secret and refresh token still need to be added as backend secrets.'}</span></div></article></div>`}
