/* ================= RC9 V0.13 RELIABILITY + COLLABORATION ================= */
state.preferences.onboardingComplete=!!state.preferences.onboardingComplete;
backendState.members=[];
backendState.driveProgress=null;
let realtimePullTimer=null;
let rendererErrorShown=false;

async function refreshWorkspaceInvites(showToast=false){
  if(!backendState.session||!backendState.workspaceId)return;
  try{
    const [invites,members]=await Promise.all([
      window.qanteakDesktop?.backendInvites?.(backendState.workspaceId) || [],
      window.qanteakDesktop?.backendMembers?.(backendState.workspaceId) || []
    ]);
    backendState.invites=Array.isArray(invites)?invites:[];
    backendState.members=Array.isArray(members)?members:[];
    if(showToast)toast('Team access refreshed',`${backendState.members.length} member${backendState.members.length===1?'':'s'} · ${backendState.invites.length} pending invite${backendState.invites.length===1?'':'s'}.`,'good');
  }catch(e){backendState.error=e?.message||'Could not load workspace invitations.'}
}

async function startWorkspaceRealtime(){
  if(!backendState.session||!backendState.workspaceId||!window.qanteakDesktop?.backendStartRealtime)return;
  try{await window.qanteakDesktop.backendStartRealtime(backendState.workspaceId);backendState.realtime=true}catch{backendState.realtime=false}
}

window.qanteakDesktop?.on?.('workspace:realtime',payload=>{
  if(!backendState.session||!backendState.workspaceId)return;
  if(payload?.type==='snapshot'){
    const rev=Number(payload?.new?.revision||0);
    if(rev<=Number(backendState.revision||0))return;
    clearTimeout(realtimePullTimer);
    realtimePullTimer=setTimeout(async()=>{
      if(backendState.busy)return;
      await pullWorkspaceSnapshot(false);
      if(!document.hidden)render(state.view);
      toast('Workspace updated','A teammate’s cloud change was loaded.','good');
    },350);
  }else if(payload?.type==='event'){
    backendState.remoteActivity=payload?.new||null;
  }
});

function workspaceIsEmpty(){return ['projects','tasks','clients','documents'].every(k=>!Array.isArray(state[k])||state[k].length===0)}
function maybeShowOnboarding(){
  if(!backendState.session||state.preferences.onboardingComplete||!workspaceIsEmpty()||$('#modal')?.classList.contains('open'))return;
  $('#modalTitle').textContent='Welcome to Qanteak';
  $('#modalSubtitle').textContent='Set up the clean workspace without adding demo data.';
  $('#modalForm').dataset.type='onboarding';
  $('#modalForm').innerHTML=`<div class="onboardingIntro"><span class="onboardingMark">Q</span><div><b>Your workspace is clean and ready.</b><p>Create the first project now, or leave it blank and start from Home.</p></div></div><div class="field"><label>First project <span class="sub">optional</span></label><input name="project" placeholder="e.g. Website launch"></div><div class="formActions"><button type="button" class="secondary" data-onboarding-skip>Keep workspace empty</button><button class="primary">Finish setup</button></div>`;
  $('#modal').classList.add('open');setScrim(true);
}
async function finishOnboarding(firstProject=''){
  state.preferences.onboardingComplete=true;
  if(firstProject.trim())state.projects.unshift({id:uid(),name:firstProject.trim(),client:'',status:'Planning',progress:0,due:'',owner:currentUserName(),description:''});
  save();await saveCloudUserSettings();closeAll();render('home');toast('Workspace ready','Qanteak setup is complete.','good');
}

document.addEventListener('click',async e=>{
  const skip=e.target.closest('[data-onboarding-skip]');if(skip){e.preventDefault();e.stopImmediatePropagation();await finishOnboarding('');return}
  const forgot=e.target.closest('#forgotPassword');if(forgot){e.preventDefault();e.stopImmediatePropagation();const email=$('#gateEmail')?.value?.trim();if(!email){setAuthStatus('Enter your email first, then choose Forgot password.','error');$('#gateEmail')?.focus();return}setAuthBusy(true);try{await window.qanteakDesktop.backendRequestPasswordReset(email);setAuthStatus('Password reset email sent. Open the link on this PC.','good')}catch(err){setAuthStatus(err?.message||'Could not send password reset email.','error')}finally{setAuthBusy(false)}return}
  const invite=e.target.closest('[data-workspace-invite]');if(invite){e.preventDefault();e.stopImmediatePropagation();$('#modalTitle').textContent='Invite teammate';$('#modalSubtitle').textContent='Send a secure 7-day invitation and choose exactly what this person can access.';$('#modalForm').dataset.type='workspaceInvite';const mods=[['projects','Projects'],['tasks','Tasks'],['reviews','Reviews'],['clients','Clients'],['files','Files'],['documents','Documents'],['business','Business']];$('#modalForm').innerHTML=`<div class="formGrid"><div class="field span2"><label>Email</label><input name="email" type="email" required placeholder="teammate@company.com"></div><div class="field"><label>Role preset</label><select name="role"><option>Editor</option><option>Admin</option><option>Viewer</option></select></div></div><div class="permissionMatrix"><div class="permissionHead"><b>Custom access</b><span>View · Create · Edit · Delete</span></div>${mods.map(([id,label])=>`<div class="permissionRow"><b>${label}</b>${['view','create','edit','delete'].map(a=>`<label><input type="checkbox" name="perm_${id}_${a}" ${['projects','tasks','reviews'].includes(id)&&a==='view'?'checked':''}> ${a}</label>`).join('')}</div>`).join('')}</div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Send invitation email</button></div>`;$('#modal').classList.add('open');setScrim(true);return}
  const revoke=e.target.closest('[data-invite-revoke]');if(revoke){e.preventDefault();e.stopImmediatePropagation();try{await window.qanteakDesktop.backendInviteRevoke(revoke.dataset.inviteRevoke);await refreshWorkspaceInvites(false);render('settings');toast('Invite revoked','The pending invitation can no longer be used.','good')}catch(err){toast('Could not revoke invite',err?.message||'Try again.')}return}
  const copy=e.target.closest('[data-invite-copy]');if(copy){e.preventDefault();e.stopImmediatePropagation();try{await navigator.clipboard.writeText(copy.dataset.inviteCopy);toast('Invite link copied','Send it to the invited email address.','good')}catch{toast('Copy failed','Select the invite again and copy it manually.')}return}
  const refresh=e.target.closest('[data-files-refresh]');if(refresh){e.preventDefault();e.stopImmediatePropagation();await refreshDriveStorage(true);render('files');return}
  const del=e.target.closest('[data-file-delete]');if(del){e.preventDefault();e.stopImmediatePropagation();const raw=String(del.dataset.fileDelete||'');if(!raw.startsWith('drive:'))return;const file=driveRows().find(x=>x.id===raw);if(!confirm(`Delete ${file?.name||'this cloud file'}? This removes the Google Drive binary and Qanteak metadata.`))return;try{await window.qanteakDesktop.backendDriveDelete({workspaceId:backendState.workspaceId,fileId:raw.slice(6)});await refreshDriveStorage(false);render('files');toast('File deleted',file?.name||'Cloud file removed.','good')}catch(err){toast('Delete failed',err?.message||'Could not remove the cloud file.')}return}
  const diag=e.target.closest('[data-export-diagnostics]');if(diag){e.preventDefault();e.stopImmediatePropagation();try{const r=await window.qanteakDesktop.exportDiagnostics();toast(r?.ok?'Diagnostics exported':'Export cancelled',r?.path||r?.message||'',r?.ok?'good':'')}catch(err){toast('Diagnostics export failed',err?.message||'Could not export the log.')}return}
},true);

document.addEventListener('submit',async e=>{
  const form=e.target;if(form?.id!=='modalForm')return;const type=form.dataset.type;
  if(!['onboarding','workspaceInvite','recovery'].includes(type))return;
  e.preventDefault();e.stopImmediatePropagation();
  if(type==='onboarding'){await finishOnboarding(String(new FormData(form).get('project')||''));return}
  if(type==='workspaceInvite'){
    const fd=new FormData(form),email=String(fd.get('email')||'').trim(),role=String(fd.get('role')||'Editor'),access=role==='Admin'?['Everything']:permissionObjectFromForm(fd);
    try{let result;try{result=await window.qanteakDesktop.backendInviteCreateAndEmail({workspaceId:backendState.workspaceId,email,role,access})}catch(primaryErr){await refreshWorkspaceInvites(false);const existing=(backendState.invites||[]).find(i=>String(i.email||'').toLowerCase()===email.toLowerCase());if(existing){result={ok:true,delivery:'pending',invite:existing}}else{const created=await window.qanteakDesktop.backendInviteCreate({workspaceId:backendState.workspaceId,email,role,access});result={ok:true,delivery:'link_only',invite:created}}}const row=result?.invite||result;const link=`qanteak://invite/${row?.token||''}`;await refreshWorkspaceInvites(false);closeAll();render('settings');try{await navigator.clipboard.writeText(link)}catch{}const msg=result?.delivery==='link_only'?'The secure invite was created. Email delivery is delayed, so the invite link was copied as a fallback.':result?.delivery==='pending'?'The secure invite is ready and email delivery is still processing. The link was also copied.':`Email delivery started via ${result?.delivery==='magic_link'?'secure sign-in email':'Qanteak invitation email'}. The secure link was also copied.`;toast('Invitation ready',msg,'good')}catch(err){toast('Invite failed',err?.message||'Could not create the invitation.')}return;
  }
  if(type==='recovery'){
    const password=String(new FormData(form).get('password')||'');if(password.length<8){toast('Password too short','Use at least 8 characters.');return}try{await window.qanteakDesktop.backendUpdatePassword(password);closeAll();setAuthStatus('Password updated. You can now sign in.','good');toast('Password updated','Your new Qanteak password is active.','good')}catch(err){toast('Password update failed',err?.message||'Open the recovery link again.')}return;
  }
},true);

function openRecoveryModal(){showAuthenticatedApp(false);$('#modalTitle').textContent='Set a new password';$('#modalSubtitle').textContent='The recovery link was verified by Qanteak.';$('#modalForm').dataset.type='recovery';$('#modalForm').innerHTML=`<div class="field"><label>New password</label><input name="password" type="password" minlength="8" autocomplete="new-password" required placeholder="At least 8 characters"></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Update password</button></div>`;$('#modal').classList.add('open');setScrim(true)}
async function handleAuthDeepLink(url){
  try{
    const u=new URL(url);
    if(u.hostname==='invite'||u.pathname.startsWith('/invite/')){const token=(u.pathname.split('/').filter(Boolean).pop()||u.hostname==='invite'&&u.pathname.slice(1));if(!backendState.session){setAuthStatus('Sign in with the invited email address, then open the invite link again.','good');showAuthenticatedApp(false);return}await window.qanteakDesktop.backendInviteAccept(token);await initBackend();await enterAuthenticatedWorkspace();toast('Invitation accepted','You now have access to the workspace.','good');return}
    const result=await window.qanteakDesktop.backendImportAuthUrl(url);
    if(result?.type==='recovery'){openRecoveryModal();return}
    setAuthStatus('Email confirmed successfully. You can sign in to Qanteak.','good');switchAuthTab('signin');
  }catch(err){setAuthStatus(err?.message||'The authentication link could not be completed.','error')}
}
window.qanteakDesktop?.on?.('auth:deep-link',handleAuthDeepLink);

window.addEventListener('error',e=>{window.qanteakDesktop?.reportRendererError?.({message:e.message,stack:e.error?.stack,source:`${e.filename||''}:${e.lineno||0}:${e.colno||0}`});window.qanteakDesktop?.backendTelemetry?.({workspaceId:backendState?.workspaceId||null,appVersion:'1.0.0-rc.9.19',platform:'renderer',kind:'renderer-error',message:e.message||'Renderer error',stack:e.error?.stack||'',context:{source:`${e.filename||''}:${e.lineno||0}:${e.colno||0}`}});if(!rendererErrorShown){rendererErrorShown=true;toast('Qanteak recovered from an interface error','A diagnostic entry was saved. If something stops working, export Diagnostics from Settings.')}});
window.addEventListener('unhandledrejection',e=>{const r=e.reason;window.qanteakDesktop?.reportRendererError?.({message:r?.message||String(r),stack:r?.stack||''});window.qanteakDesktop?.backendTelemetry?.({workspaceId:backendState?.workspaceId||null,appVersion:'1.0.0-rc.9.19',platform:'renderer',kind:'unhandled-rejection',message:r?.message||String(r),stack:r?.stack||''});});

function formatBytes(n){n=Number(n||0);if(!n)return'—';const u=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${u[i]}`}
