files=function(){let rows=visibleFileRows();const tab=state.tabs.files;if(tab==='versions')rows=rows.filter(f=>/v\d+/i.test(f.version||''));if(tab==='delivery')rows=rows.filter(f=>f.group==='delivery');if(tab==='connected')rows=rows.filter(f=>f.project!=='Unassigned');const storageStatus=backendState.drive.configured?'Google Drive connected':backendState.drive.error?'Drive unavailable':'Drive setup required';const progress=backendState.driveProgress?`<div class="uploadProgress"><b>${esc(backendState.driveProgress.name||'Uploading')}</b><span>${backendState.driveProgress.index||0}/${backendState.driveProgress.total||0}</span></div>`:'';return `<div class="surfaceToolbar">${tabs('files',[['all','All files'],['versions','Versions'],['delivery','Delivery'],['connected','Connected']])}<div class="toolbarActions"><button class="secondary" data-files-refresh>Refresh</button><button class="primary" id="uploadFiles"><i class="fi fi-rr-cloud-upload-alt"></i> Upload files</button></div></div>${progress}<div class="fileGrid"><article class="card sectionCard">${sectionTitle(tab==='delivery'?'Delivery files':tab==='versions'?'Version groups':'Smart files',`${storageStatus} · project-aware cloud files.`)} ${filesTable(rows)}</article><aside class="card insight">${sectionTitle('Cloud storage','Google Drive + Supabase permissions.')}<div class="insightItem"><i>☁</i><div><b>${esc(storageStatus)}</b><p>${backendState.drive.configured?'File binaries live in Qanteak Storage on Google Drive.':'Google OAuth backend secrets are still required before binary uploads can go live.'}</p></div></div><div class="insightItem"><i>↻</i><div><b>Recoverable transfers</b><p>Uploads report per-file progress and failed operations leave the existing metadata untouched.</p></div></div><div class="insightItem"><i>🔒</i><div><b>Workspace isolated</b><p>Supabase membership is checked before file metadata or binaries are returned.</p></div></div></aside></div>`}
