/* ================= RC9 V0.16 SHEETS + LIFECYCLE + PERMISSIONS ================= */
const V016_ENTITY_META={
  project:{collection:'projects',module:'projects',label:'project'},
  task:{collection:'tasks',module:'tasks',label:'task'},
  review:{collection:'reviews',module:'reviews',label:'review'},
  client:{collection:'clients',module:'clients',label:'client'},
  document:{collection:'documents',module:'documents',label:'document'},
  file:{collection:'files',module:'files',label:'file'},
  invoice:{collection:'invoices',module:'business',label:'invoice'},
  estimate:{collection:'estimates',module:'business',label:'estimate'},
  expense:{collection:'expenses',module:'business',label:'expense'},
  lead:{collection:'leads',module:'clients',label:'lead'},
  automation:{collection:'automations',module:'business',label:'automation'}
};

function v016Entity(kind,id){const meta=V016_ENTITY_META[kind];return meta?(state[meta.collection]||[]).find(x=>String(x.id)===String(id)):null}
function v016Can(kind,action){const meta=V016_ENTITY_META[kind];return !!meta&&accessAllows(meta.module,action)}
function v016LifecycleActions(kind,id){const meta=V016_ENTITY_META[kind];if(!meta)return '';const item=v016Entity(kind,id);const archived=!!item?.archivedAt;const archiveAllowed=v016Can(kind,'edit');const deleteAllowed=v016Can(kind,'delete');if(!archiveAllowed&&!deleteAllowed)return '';return `<div class="entityLifecycleBar"><div><b>Item actions</b><span>${archived?'This item is archived.':'Archive keeps the item recoverable. Delete removes it permanently.'}</span></div><div class="entityLifecycleButtons">${archiveAllowed?`<button type="button" class="secondary" data-entity-archive data-entity-kind="${kind}" data-entity-id="${esc(id)}">${archived?'Restore':'Archive'}</button>`:''}${deleteAllowed?`<button type="button" class="miniButton dangerAction" data-entity-delete data-entity-kind="${kind}" data-entity-id="${esc(id)}">Delete</button>`:''}</div></div>`}
function v016AppendLifecycle(kind,id){const host=$('#detailBody');if(!host||host.querySelector('.entityLifecycleBar'))return;host.insertAdjacentHTML('beforeend',v016LifecycleActions(kind,id))}

function v016Archive(kind,id){const item=v016Entity(kind,id);if(!item||!v016Can(kind,'edit'))return;item.archivedAt=item.archivedAt?null:new Date().toISOString();save();closeAll();render(state.view);toast(item.archivedAt?'Archived':'Restored',`${V016_ENTITY_META[kind].label[0].toUpperCase()+V016_ENTITY_META[kind].label.slice(1)} ${item.archivedAt?'moved out of active views':'returned to active views'}.`,'good')}
async function v016Delete(kind,id){const meta=V016_ENTITY_META[kind];if(!meta||!v016Can(kind,'delete'))return;if(kind==='file'&&String(id).startsWith('drive:')){const cloudId=String(id).slice(6);if(!confirm('Delete this file permanently? This removes the Google Drive binary and Qanteak metadata.'))return;try{await window.qanteakDesktop.backendDriveDelete({workspaceId:backendState.workspaceId,fileId:cloudId});state.files=state.files.filter(x=>!(x.archiveMarker&&String(x.cloudId)===cloudId));await refreshDriveStorage(false);save();closeAll();render('files');toast('File deleted','The cloud file was removed permanently.','good')}catch(err){toast('Delete failed',err?.message||'Could not delete the cloud file.')}return}const item=v016Entity(kind,id);if(!item)return;if(!confirm(`Delete this ${meta.label} permanently? This cannot be undone.`))return;state[meta.collection]=state[meta.collection].filter(x=>String(x.id)!==String(id));save();closeAll();render(state.view);toast('Deleted',`The ${meta.label} was removed permanently.`,'good')}

function v016ArchivedRows(){const rows=[];for(const [kind,meta] of Object.entries(V016_ENTITY_META)){for(const item of (state[meta.collection]||[])){if(item.archivedAt&&!item.archiveMarker)rows.push({kind,id:item.id,label:item.name||item.title||item.number||item.email||item.file_name||meta.label,when:item.archivedAt})}}for(const marker of (state.files||[]).filter(x=>x.archiveMarker&&x.archivedAt))rows.push({kind:'file',id:`drive:${marker.cloudId}`,label:marker.name||'Cloud file',when:marker.archivedAt,cloud:true});return rows.sort((a,b)=>String(b.when).localeCompare(String(a.when)))}

const v016SettingsAccountBase=settingsAccount;
settingsAccount=function(){const rows=v016ArchivedRows();return v016SettingsAccountBase()+`<article class="card sectionCard">${sectionTitle('Archived items','Archived work stays recoverable until you permanently delete it.')}<div>${rows.length?rows.map(r=>`<div class="inviteRow"><div><b>${esc(r.label)}</b><span>${esc(V016_ENTITY_META[r.kind]?.label||r.kind)} · archived ${new Date(r.when).toLocaleString()}</span></div><div class="fileActions"><button class="miniButton" data-restore-entity data-entity-kind="${r.kind}" data-entity-id="${esc(r.id)}">Restore</button>${v016Can(r.kind,'delete')?`<button class="miniButton dangerText" data-entity-delete data-entity-kind="${r.kind}" data-entity-id="${esc(r.id)}">Delete</button>`:''}</div></div>`).join(''):'<div class="empty">Nothing is archived.</div>'}</div></article>`}

function v016WithActiveRows(fn,keepCloudMarkers=false){const names=['projects','tasks','clients','leads','reviews','documents','files','invoices','estimates','expenses','automations'];const originals={};for(const name of names){originals[name]=state[name];state[name]=(state[name]||[]).filter(x=>name==='files'&&keepCloudMarkers&&x.archiveMarker?true:!x.archivedAt&&!x.archiveMarker)}try{return fn()}finally{for(const name of names)state[name]=originals[name]}}
const v016HomeBase=home,v016WorkBase=work,v016ClientsBase=clients,v016DocumentsBase=documents,v016FilesBase=files,v016BusinessBase=business,v016AutomationsBase=automations;
home=function(){return v016WithActiveRows(v016HomeBase)};
work=function(){return v016WithActiveRows(v016WorkBase)};
clients=function(){return v016WithActiveRows(v016ClientsBase)};
documents=function(){return v016WithActiveRows(v016DocumentsBase)};
files=function(){return v016WithActiveRows(v016FilesBase,true)};
business=function(){return v016WithActiveRows(v016BusinessBase)};
automations=function(){return v016WithActiveRows(v016AutomationsBase)};
Object.assign(renderers,{home,work,clients,documents,files,business,automations,settings});

const v016VisibleFileRowsBase=visibleFileRows;
visibleFileRows=function(){const markers=new Set((state.files||[]).filter(x=>x.archiveMarker&&x.archivedAt).map(x=>String(x.cloudId)));return v016VisibleFileRowsBase().filter(f=>!f.archivedAt&&!f.archiveMarker&&!(String(f.id).startsWith('drive:')&&markers.has(String(f.id).slice(6))))};

function v016ArchiveCloudFile(file){const cloudId=String(file.id).slice(6);if((state.files||[]).some(x=>x.archiveMarker&&String(x.cloudId)===cloudId))return;state.files.push({id:`cloud-archive-${cloudId}`,archiveMarker:true,cloudId,name:file.name||'Cloud file',archivedAt:new Date().toISOString()});save();closeAll();render('files');toast('Archived','The cloud file is hidden from active Files and can be restored in Settings.','good')}
function v016Restore(kind,id){if(kind==='file'&&String(id).startsWith('drive:')){const cloudId=String(id).slice(6);state.files=state.files.filter(x=>!(x.archiveMarker&&String(x.cloudId)===cloudId));save();render('settings');toast('Restored','The cloud file is visible again.','good');return}const item=v016Entity(kind,id);if(!item)return;item.archivedAt=null;save();render('settings');toast('Restored',`The ${V016_ENTITY_META[kind]?.label||'item'} is active again.`,'good')}

const v016OpenProjectBase=openProject;
openProject=function(id){v016OpenProjectBase(id);v016AppendLifecycle('project',id)};
const v016OpenClientBase=openClient;
openClient=function(id){v016OpenClientBase(id);const c=v016Entity('client',id);if(c?.phone)$('#detailSubtitle').textContent=`${c.relationship} · ${c.phone}`;v016AppendLifecycle('client',id)};
const v016OpenInvoiceBase=openInvoice;
openInvoice=function(id){v016OpenInvoiceBase(id);v016AppendLifecycle('invoice',id)};

function v016OpenTask(id){const t=v016Entity('task',id);if(!t)return;$('#detailTitle').textContent=t.title;$('#detailSubtitle').textContent=`${t.project||'Unassigned'} · ${t.done?'Completed':'Open'}`;$('#detailBody').innerHTML=`<div class="detailGrid"><div class="detailMetric"><span>Project</span><b>${esc(t.project||'Unassigned')}</b></div><div class="detailMetric"><span>Due</span><b>${esc(t.due||fmtDate(t.date)||'No due date')}</b></div><div class="detailMetric"><span>Priority</span><b>${esc(t.priority||'Normal')}</b></div></div>${v016LifecycleActions('task',id)}`;$('#detailModal').classList.add('open');setScrim(true)}
function v016OpenReview(id){const r=v016Entity('review',id);if(!r)return;$('#detailTitle').textContent=r.name;$('#detailSubtitle').textContent=`${r.client||'Client'} · ${r.status||'Waiting'}`;$('#detailBody').innerHTML=`<div class="detailGrid"><div class="detailMetric"><span>Project</span><b>${esc(r.project||'Unassigned')}</b></div><div class="detailMetric"><span>Status</span><b>${esc(r.status||'Waiting')}</b></div><div class="detailMetric"><span>Due</span><b>${esc(fmtDate(r.due)||r.due||'No due date')}</b></div></div>${v016LifecycleActions('review',id)}`;$('#detailModal').classList.add('open');setScrim(true)}
function v016OpenFile(id){const f=visibleFileRows().find(x=>String(x.id)===String(id));if(!f)return;$('#detailTitle').textContent=f.name;$('#detailSubtitle').textContent=`${f.project||'Unassigned'} · ${f.version||'File'}`;const archiveButton=v016Can('file','edit')?`<button type="button" class="secondary" data-entity-archive data-entity-kind="file" data-entity-id="${esc(id)}">Archive</button>`:'';const deleteButton=v016Can('file','delete')?`<button type="button" class="miniButton dangerAction" data-entity-delete data-entity-kind="file" data-entity-id="${esc(id)}">Delete</button>`:'';$('#detailBody').innerHTML=`<div class="detailGrid"><div class="detailMetric"><span>Project</span><b>${esc(f.project||'Unassigned')}</b></div><div class="detailMetric"><span>Version</span><b>${esc(f.version||'Current')}</b></div><div class="detailMetric"><span>Updated</span><b>${esc(f.updated||'')}</b></div></div><div class="entityLifecycleBar"><div><b>Item actions</b><span>Archive keeps the file recoverable. Delete removes it permanently.</span></div><div class="entityLifecycleButtons">${archiveButton}${deleteButton}</div></div>`;$('#detailModal').classList.add('open');setScrim(true)}

const v016TaskRowsBase=taskRows;
taskRows=function(tasks=state.tasks){return tasks.map(t=>`<div class="taskItem hasEntityOpen ${t.done?'done':''}"><button class="taskCheck" data-task="${t.id}">${t.done?'✓':''}</button><div><b>${esc(t.title)}</b><span>${esc(t.project)}</span></div><time>${esc(t.due)}</time><button type="button" class="miniButton" data-open-task="${t.id}">Open</button></div>`).join('')};
const v016WorkReviewsBase=workReviews;
workReviews=function(){return `<article class="card sectionCard">${sectionTitle('Reviews','Reviews now live in Work, beside the projects and tasks they belong to.','<button class="primary" data-create="review"><i class="fi fi-rr-plus"></i> Review</button>')}<div class="listCard">${state.reviews.map(r=>`<div class="listRow"><div><span class="title">${esc(r.name)}</span><span class="sub">${esc(r.client)} · ${esc(r.project)}</span></div><div>${fmtDate(r.due)}</div><div><span class="chip ${statusKind(r.status)}">${esc(r.status)}</span></div><div>Client review</div><div class="fileActions"><button class="miniButton" data-open-review="${r.id}">Open</button><button class="miniButton" data-review="${r.id}">${r.status==='Approved'?'Reopen':'Approve'}</button></div></div>`).join('')}</div></article>`};
filesTable=function(rows){return `<div class="tableWrap"><table class="dataTable"><thead><tr><th>Name</th><th>Project</th><th>Version</th><th>Review</th><th>Updated</th><th></th></tr></thead><tbody>${rows.map(f=>`<tr><td><div class="fileName"><span class="fileIcon">${esc(f.name.split('.').pop().slice(0,3).toUpperCase())}</span><strong>${esc(f.name)}</strong></div></td><td>${esc(f.project)}</td><td>${esc(f.version)}</td><td><span class="chip ${statusKind(f.review)}">${esc(f.review)}</span></td><td>${esc(f.updated)}</td><td><div class="fileActions"><button class="miniButton" data-open-file="${esc(f.id)}">Open</button><button class="miniButton" data-file-download="${esc(f.id)}" ${f.path||f.cloud?'':'disabled'}><i class="fi fi-rr-download"></i> Download</button></div></td></tr>`).join('')}</tbody></table></div>`};

function v016ColumnName(index){let n=index+1,out='';while(n>0){n--;out=String.fromCharCode(65+n%26)+out;n=Math.floor(n/26)}return out}
function v016EnsureSheet(doc){if(!doc.sheet||typeof doc.sheet!=='object')doc.sheet={rows:24,cols:10,cells:{}};doc.sheet.rows=Math.max(12,Number(doc.sheet.rows)||24);doc.sheet.cols=Math.min(26,Math.max(6,Number(doc.sheet.cols)||10));if(!doc.sheet.cells||typeof doc.sheet.cells!=='object')doc.sheet.cells={};return doc.sheet}
function v016SheetCellAddress(row,col){return `${v016ColumnName(col)}${row+1}`}
function v016SheetCellRaw(doc,address){return String(v016EnsureSheet(doc).cells[address]??'')}
function v016SheetNumber(doc,address,stack=new Set()){if(stack.has(address))return 0;stack.add(address);const raw=v016SheetCellRaw(doc,address);const value=raw.startsWith('=')?v016EvalFormula(doc,raw,stack):raw;stack.delete(address);const n=Number(String(value).replace(/,/g,''));return Number.isFinite(n)?n:0}
function v016RangeAddresses(a,b){const m1=/^([A-Z]+)(\d+)$/.exec(a),m2=/^([A-Z]+)(\d+)$/.exec(b);if(!m1||!m2)return[];const toCol=x=>{let n=0;for(const ch of x)n=n*26+(ch.charCodeAt(0)-64);return n-1};const c1=toCol(m1[1]),c2=toCol(m2[1]),r1=Number(m1[2])-1,r2=Number(m2[2])-1,out=[];for(let r=Math.min(r1,r2);r<=Math.max(r1,r2);r++)for(let c=Math.min(c1,c2);c<=Math.max(c1,c2);c++)out.push(v016SheetCellAddress(r,c));return out}
function v016EvalFormula(doc,formula,stack=new Set()){const src=String(formula||'').trim().toUpperCase();if(!src.startsWith('='))return formula;let m=/^=(SUM|AVERAGE|MIN|MAX)\(([A-Z]+\d+):([A-Z]+\d+)\)$/.exec(src);if(m){const nums=v016RangeAddresses(m[2],m[3]).map(a=>v016SheetNumber(doc,a,new Set(stack)));if(!nums.length)return 0;if(m[1]==='SUM')return nums.reduce((a,b)=>a+b,0);if(m[1]==='AVERAGE')return nums.reduce((a,b)=>a+b,0)/nums.length;if(m[1]==='MIN')return Math.min(...nums);return Math.max(...nums)}m=/^=([A-Z]+\d+)$/.exec(src);if(m)return v016SheetNumber(doc,m[1],new Set(stack));m=/^=([A-Z]+\d+|[-+]?\d+(?:\.\d+)?)\s*([+\-*/])\s*([A-Z]+\d+|[-+]?\d+(?:\.\d+)?)$/.exec(src);if(m){const val=x=>/^[A-Z]+\d+$/.test(x)?v016SheetNumber(doc,x,new Set(stack)):Number(x);const a=val(m[1]),b=val(m[3]);if(m[2]==='+')return a+b;if(m[2]==='-')return a-b;if(m[2]==='*')return a*b;return b===0?'#DIV/0!':a/b}return '#FORMULA!'}
function v016SheetDisplay(doc,address){const raw=v016SheetCellRaw(doc,address);if(!raw.startsWith('='))return raw;const v=v016EvalFormula(doc,raw);return typeof v==='number'&&Number.isFinite(v)?String(Math.round(v*1000000)/1000000):String(v)}
function v016SheetEditor(doc){const sh=v016EnsureSheet(doc);const cols=Array.from({length:sh.cols},(_,i)=>v016ColumnName(i));const rows=Array.from({length:sh.rows},(_,r)=>`<tr><th class="sheetRowHead">${r+1}</th>${cols.map((_,c)=>{const a=v016SheetCellAddress(r,c),raw=v016SheetCellRaw(doc,a),display=v016SheetDisplay(doc,a);return `<td><input class="sheetCell" data-sheet-cell="${a}" data-sheet-raw="${esc(raw)}" value="${esc(display)}" autocomplete="off" spellcheck="false"></td>`}).join('')}</tr>`).join('');return `<div class="sheetShell"><article class="card sheetEditor"><input id="docTitle" class="sheetTitle" value="${esc(doc.title)}" aria-label="Sheet title"><div class="editorMeta">Project: ${esc(doc.project)} · Client: ${esc(doc.client)} · Owner: ${esc(doc.owner)}</div><div class="sheetFormulaBar"><span id="sheetNameBox">A1</span><span class="sheetFx">fx</span><input id="sheetFormula" aria-label="Formula bar" placeholder="Enter a value or formula, for example =SUM(A1:A5)"></div><div class="sheetGridWrap"><table class="sheetGrid"><thead><tr><th class="sheetCorner"></th>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div><div class="editorActions"><button class="secondary" data-tab-view="documents" data-tab="documents">Back to documents</button><button class="primary" data-save-doc="${doc.id}">Save sheet</button></div>${v016LifecycleActions('document',doc.id)}</article><aside class="card contextPanel"><h3>Sheet context</h3><div class="contextBlock"><b>Project</b><span>${esc(doc.project)}</span></div><div class="contextBlock"><b>Client</b><span>${esc(doc.client)}</span></div><div class="contextBlock"><b>Related files</b><span>${state.files.filter(f=>f.project===doc.project&&!f.archivedAt&&!f.archiveMarker).length} project assets</span></div><div class="contextBlock"><b>Open tasks</b><span>${state.tasks.filter(t=>t.project===doc.project&&!t.done&&!t.archivedAt).length} tasks</span></div><button class="primary" style="width:100%" id="askFromDoc">✦ Ask about this sheet</button></aside></div>`}
function v016RefreshSheetCells(doc){$$('.sheetCell').forEach(input=>{const address=input.dataset.sheetCell;if(document.activeElement!==input){input.dataset.sheetRaw=v016SheetCellRaw(doc,address);input.value=v016SheetDisplay(doc,address)}})}
function v016BindSheet(doc){let selected='A1';const formula=$('#sheetFormula'),name=$('#sheetNameBox');const selectCell=input=>{selected=input.dataset.sheetCell||'A1';if(name)name.textContent=selected;if(formula)formula.value=v016SheetCellRaw(doc,selected);input.value=v016SheetCellRaw(doc,selected)};$$('.sheetCell').forEach(input=>{input.addEventListener('focus',()=>selectCell(input));input.addEventListener('input',()=>{if(formula&&document.activeElement===input)formula.value=input.value});input.addEventListener('blur',()=>{const address=input.dataset.sheetCell,raw=input.value;v016EnsureSheet(doc).cells[address]=raw;input.dataset.sheetRaw=raw;input.value=v016SheetDisplay(doc,address);v016RefreshSheetCells(doc)})});formula?.addEventListener('focus',()=>{formula.value=v016SheetCellRaw(doc,selected)});formula?.addEventListener('change',()=>{v016EnsureSheet(doc).cells[selected]=formula.value;const cell=$(`.sheetCell[data-sheet-cell="${selected}"]`);if(cell){cell.dataset.sheetRaw=formula.value;cell.value=v016SheetDisplay(doc,selected)}v016RefreshSheetCells(doc)});const first=$('.sheetCell');if(first){selected=first.dataset.sheetCell;if(name)name.textContent=selected;if(formula)formula.value=v016SheetCellRaw(doc,selected)}}

