openDocument=function(id){state.tabs.documents='documents';render('documents');const d=state.documents.find(x=>x.id===id);if(!d)return;$('#content').innerHTML=`<div class="surfaceToolbar">${tabs('documents',[['documents','Documents'],['knowledge','Knowledge'],['templates','Templates']])}<button class="primary" data-create="document">+ Document</button></div>${d.type==='sheet'?v016SheetEditor(d):documentEditor(d)}${d.type==='sheet'?'':v016LifecycleActions('document',d.id)}`;bindContent();if(d.type==='sheet')v016BindSheet(d);$('#askFromDoc')?.addEventListener('click',openAi)};

