openCreate=function(type,prefill=''){if(type==='slide'){toast('Slides removed','Qanteak now supports Documents, Notes and Sheets.');return}$('#modal .modalCard')?.classList.remove('permissionModalCard');if(type==='client'){const form=$('#modalForm');$('#modalTitle').textContent='New client';$('#modalSubtitle').textContent='Add a client relationship.';form.dataset.type='client';form.innerHTML=`<div class="formGrid"><div class="field span2"><label>Client name</label><input name="title" required value="${esc(prefill)}"></div><div class="field"><label>Email</label><input name="field2" type="email"></div><div class="field"><label>Phone number</label><input name="phone" type="tel" placeholder="+962 7 9000 0000"></div><div class="field span2"><label>Company</label><input name="field3"></div></div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Create</button></div>`;$('#modal').classList.add('open');$$('[data-close="modal"]').forEach(b=>b.onclick=closeAll);setScrim(true);setTimeout(()=>form.querySelector('input')?.focus(),30);return}v016OpenCreateBase(type,prefill);if(['document','note','sheet'].includes(type))$('#modalForm option[value="slide"]')?.remove()};

