function v016PermissionRows(access,invite=false){const mods=[['projects','Projects'],['tasks','Tasks'],['reviews','Reviews'],['clients','Clients'],['files','Files'],['documents','Documents'],['business','Business']];const acts=[['view','View'],['create','Create'],['edit','Edit'],['delete','Delete']];const checked=(mod,act)=>invite?(['projects','tasks','reviews'].includes(mod)&&act==='view'):(access?.includes?.('Everything')||access?.[mod]?.all||access?.[mod]?.[act]);return `<div class="permissionGrid"><div class="permissionGridHead"><span>Module</span>${acts.map(([,label])=>`<span>${label}</span>`).join('')}<span>All</span></div>${mods.map(([mod,label])=>`<div class="permissionGridRow"><div class="permissionModule"><b>${label}</b></div>${acts.map(([act,label])=>`<label class="permissionCheck" title="${label} ${label}"><input type="checkbox" name="perm_${mod}_${act}" ${checked(mod,act)?'checked':''}><span aria-hidden="true"></span></label>`).join('')}<button type="button" class="permissionRowAll" data-permission-row="${mod}">All</button></div>`).join('')}</div>`}
function v016OpenInvite(){const form=$('#modalForm'),card=$('#modal .modalCard');card?.classList.add('permissionModalCard');$('#modalTitle').textContent='Invite teammate';$('#modalSubtitle').textContent='Send a secure 7-day invitation and choose exactly what this person can access.';form.dataset.type='workspaceInvite';form.innerHTML=`<div class="permissionIdentity"><div class="field"><label>Email</label><input name="email" type="email" required placeholder="teammate@company.com"></div><div class="field"><label>Role preset</label><select name="role"><option>Editor</option><option>Admin</option><option>Viewer</option></select></div></div><div class="permissionPanel"><div class="permissionPanelHead"><div><b>Custom access</b><span>Choose exactly what this teammate can view and change.</span></div><div class="permissionPanelActions"><button type="button" class="miniButton" data-permission-select="all">Select all</button><button type="button" class="miniButton" data-permission-select="none">Clear</button></div></div>${v016PermissionRows(null,true)}</div><div class="formActions"><button type="button" class="secondary" data-close="modal">Cancel</button><button class="primary">Send invitation email</button></div>`;$('#modal').classList.add('open');setScrim(true);setTimeout(()=>form.querySelector('[name=email]')?.focus(),30)}
