window.addEventListener('click',async e=>{
  const invite=e.target.closest?.('[data-workspace-invite]');if(invite){e.preventDefault();e.stopImmediatePropagation();v016OpenInvite();return}
  const member=e.target.closest?.('[data-member-permissions]');if(member){e.preventDefault();e.stopImmediatePropagation();v016OpenMemberPermissions(member.dataset.memberPermissions);return}
  const select=e.target.closest?.('[data-permission-select]');if(select){e.preventDefault();e.stopImmediatePropagation();const checked=select.dataset.permissionSelect==='all';$('#modalForm')?.querySelectorAll('.permissionGrid input[type=checkbox]').forEach(x=>x.checked=checked);return}
  const row=e.target.closest?.('[data-permission-row]');if(row){e.preventDefault();e.stopImmediatePropagation();const inputs=$$('#modalForm input[name^="perm_'+row.dataset.permissionRow+'_"]');const next=!inputs.every(x=>x.checked);inputs.forEach(x=>x.checked=next);return}
  const archive=e.target.closest?.('[data-entity-archive]');if(archive){e.preventDefault();e.stopImmediatePropagation();const kind=archive.dataset.entityKind,id=archive.dataset.entityId;if(kind==='file'&&String(id).startsWith('drive:')){const f=visibleFileRows().find(x=>String(x.id)===String(id));if(f)v016ArchiveCloudFile(f)}else v016Archive(kind,id);return}
  const del=e.target.closest?.('[data-entity-delete]');if(del){e.preventDefault();e.stopImmediatePropagation();await v016Delete(del.dataset.entityKind,del.dataset.entityId);return}
  const restore=e.target.closest?.('[data-restore-entity]');if(restore){e.preventDefault();e.stopImmediatePropagation();v016Restore(restore.dataset.entityKind,restore.dataset.entityId);return}
  const task=e.target.closest?.('[data-open-task]');if(task){e.preventDefault();e.stopImmediatePropagation();v016OpenTask(task.dataset.openTask);return}
  const review=e.target.closest?.('[data-open-review]');if(review){e.preventDefault();e.stopImmediatePropagation();v016OpenReview(review.dataset.openReview);return}
  const file=e.target.closest?.('[data-open-file]');if(file){e.preventDefault();e.stopImmediatePropagation();v016OpenFile(file.dataset.openFile);return}
},true);

